/** The facts a pack page may print. Each row is a recorded value or it is absent. */
function workshopFactRows(item) {
  const rows = []
  rows.push({ label: 'Content hash', value: item.content_hash })
  rows.push({
    label: 'Integrity',
    value: item.integrity.hashes_match
      ? `Every file matches the manifest (${plural(item.integrity.file_count, 'file', 'files')}, ${workshopFileSize(item.integrity.expanded_bytes)})`
      : 'Hashes did not match when this pack was read'
  })
  rows.push({
    label: 'Automated checks',
    value: item.trust_labels.indexOf('automated_checks_passed') >= 0 ? 'Passed' : 'Not recorded'
  })
  rows.push({
    label: 'Human review',
    value: item.trust_labels.indexOf('human_review_recorded') >= 0 ? 'Recorded' : 'None recorded'
  })
  rows.push({
    label: 'Model support',
    value: item.trust_labels.indexOf('model_assessed_support') >= 0 ? 'Sources judged by a model, not a person' : 'None recorded'
  })
  rows.push({ label: 'Provenance', value: `${item.recipe} recipe · ${item.locale || 'no locale declared'}` })
  if (item.installed && item.installed.evidence_summary) {
    const summary = item.installed.evidence_summary
    rows.push({
      label: 'Your evidence',
      value: `${summary.independent} of ${summary.total_objectives} objectives have independent evidence${summary.review_due ? ` · ${summary.review_due} due` : ''}`
    })
  }
  return rows
}

function WorkshopDiscover({ catalog, layout, motion, prefs, onOpen, onInstall, busyInstall, onFavorite, onOpenCourse }) {
  const [filter, setFilter] = useState('all')
  const items = catalog.items || []
  const favoriteSet = new Set(prefs.favorites)
  const featured = items.find((item) => item.pack_id === catalog.featured_pack_id) || items[0]
  const categories = []
  for (const item of items) {
    for (const category of item.categories || []) {
      if (categories.indexOf(category) < 0) categories.push(category)
    }
  }
  const shown = filter === 'all' ? items : items.filter((item) => (item.categories || []).indexOf(filter) >= 0)
  const savedItems = items.filter((item) => favoriteSet.has(item.pack_id) || (prefs.categories || {})[item.pack_id])
  // Shelves follow each pack's own first category, in catalogue order. The catalogue is the
  // taxonomy: this surface never invents a shelf a pack does not already belong to, and the
  // filter pills above are drawn from the same field.
  const shelves = []
  if (filter === 'all') {
    const order = []
    for (const item of items) {
      const name = (item.categories || [])[0] || 'Other packs'
      if (order.indexOf(name) < 0) order.push(name)
    }
    for (const name of order) {
      shelves.push({
        title: name,
        items: items.filter((item) => ((item.categories || [])[0] || 'Other packs') === name)
      })
    }
  } else {
    shelves.push({ title: filter, items: shown })
  }
  const shelfKey = `${filter}-${shown.map((item) => item.pack_id).join(',')}`
  const cardProps = {
    motion,
    layout,
    onOpen,
    onInstall,
    busy: null,
    onFavorite,
    onOpenCourse
  }
  return jsxs('div', {
    'data-cb-workshop-discover': '',
    style: { display: 'flex', flexDirection: 'column', gap: '1.5rem', minWidth: 0 },
    children: [
      featured
        ? jsx(WorkshopHero, { item: featured, layout, motion, onOpen, onInstall, onContinue: onOpenCourse, busy: busyInstall === featured.pack_id })
        : null,
      jsxs('div', {
        style: {
          display: 'flex',
          flexWrap: 'wrap',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '0.5rem 1rem'
        },
        children: [
          jsx('h2', {
            style: {
              margin: 0,
              fontFamily: CB_SERIF,
              fontSize: CB_TYPE.heading,
              fontWeight: 600,
              color: 'var(--cb-ink)'
            },
            children: 'Find a pack',
          }),
          jsxs('div', {
            'data-cb-workshop-filter': '',
            role: 'group',
            'aria-label': 'Filter packs by category',
            style: { display: 'flex', flexWrap: 'wrap', gap: '0.35rem' },
            children: [
              jsx('button', {
                type: 'button',
                'aria-pressed': filter === 'all' ? 'true' : 'false',
                onClick: () => setFilter('all'),
                style: workshopFilterStyle(filter === 'all'),
                children: 'All'
              })
            ].concat(
              categories.map((category) =>
                jsx('button', {
                  type: 'button',
                  'aria-pressed': filter === category ? 'true' : 'false',
                  onClick: () => setFilter(category),
                  style: workshopFilterStyle(filter === category),
                  children: category
                }, category)
              )
            )
          })
        ]
      }),
      filter === 'all' && savedItems.length
        ? jsx(WorkshopShelf, {
            ...cardProps,
            title: 'Your shelf',
            caption: 'Saved or labelled on this device',
            items: savedItems
          })
        : null,
      ...shelves.map((shelf) =>
        jsx(WorkshopShelf, {
          ...cardProps,
          title: shelf.title,
          caption: plural(shelf.items.length, 'pack', 'packs'),
          items: shelf.items
        }, `${shelfKey}-${shelf.title}`)
      )
    ]
  })
}

function workshopFilterStyle(selected) {
  return {
    minHeight: '44px',
    padding: '0.25rem 0.7rem',
    fontFamily: CB_SANS,
    fontSize: CB_TYPE.caption,
    fontWeight: selected ? 600 : 400,
    color: selected ? 'var(--cb-ink)' : 'var(--cb-ink-soft)',
    background: selected ? 'var(--cb-lamp-soft)' : 'transparent',
    border: `1px solid ${selected ? 'var(--cb-lamp)' : 'var(--cb-rule)'}`,
    borderRadius: '999px',
    cursor: 'pointer'
  }
}

/** The imported-pack ledger: what this profile holds, at which version, from where. */
function WorkshopProvenance({ implemented, motion, layout }) {
  const payload = { filter: 'all', limit: 100 }
  const key = JSON.stringify(payload)
  const { status, data, error, stale, reload } = useRpcQuery('pack.list', payload, key, backendSupports('pack.list'))
  const [selected, setSelected] = useState(null)
  const [preview, setPreview] = useState(null)
  const rows = data && Array.isArray(data.items) ? data.items : []
  const open = useCallback(async (row) => {
    setSelected(`${row.pack_id}@${row.pack_version}`)
    setPreview(null)
    const response = await rpc('pack.inspect', { pack_id: row.pack_id, pack_version: row.pack_version })
    if (response && response.ok) setPreview(response.result)
    else setPreview({ error: (response && response.error) || { message: 'This pack could not be inspected.' } })
  }, [])
  return jsxs('div', {
    'data-cb-workshop-provenance': '',
    style: { display: 'flex', flexDirection: 'column', gap: '1rem', maxWidth: CB_MEASURE, minWidth: 0 },
    children: [
      jsx(PlateHead, {
        title: 'The Workshop ledger',
        label: 'Imported and shared packs',
        caption:
          'Every pack this profile holds, the version it was imported at, where it came from and the hash that was verified. There is no publishing, no upload and no version the backend did not record.'
      }),
      jsx('p', {
        id: 'cb-workshop-ledger-note',
        style: {
          margin: 0,
          maxWidth: CB_MEASURE,
          fontFamily: CB_SANS,
          fontSize: CB_TYPE.caption,
          lineHeight: 1.5,
          color: 'var(--cb-ink-soft)'
        },
        children:
          'A row is a recorded import, not a verdict: it names the version, the source and the hash this profile verified at import. Inspecting a row re-hashes the pack now. No row claims a human review.'
      }),
      status === 'loading' && !data
        ? jsx('div', { className: 'py-6', children: jsx(sdk.Loader, { label: 'Reading the pack ledger' }) })
        : status === 'error' && !data
          ? jsxs('div', {
              style: { display: 'flex', flexDirection: 'column', gap: '0.5rem' },
              children: [
                jsx(EmptyState, {
                  title: 'The pack ledger could not be read',
                  description: `${(error && error.code) || 'HOST_UNAVAILABLE'}: ${describeError(error)}`
                }),
                jsx(CbAction, { variant: 'tertiary', onClick: reload, className: 'self-start', children: 'Try again' })
              ]
            })
          : rows.length === 0
            ? jsx(EmptyState, {
                title: 'No packs on this profile yet',
                description:
                  'Add a pack from Discover, or import one from a file in the Library tab. This ledger then records exactly what arrived.'
              })
            : jsxs('div', {
                style: { display: 'flex', flexDirection: 'column', gap: '0.5rem', minWidth: 0 },
                children: [
                  stale
                    ? jsx('p', {
                        style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' },
                        children: 'Reconnecting. Showing the last pack ledger read.'
                      })
                    : null,
                  rows.map((row) => {
                    const rowKey = `${row.pack_id}@${row.pack_version}`
                    const current = selected === rowKey
                    return jsxs('article', {
                      'data-cb-workshop-ledger-row': rowKey,
                      style: {
                        display: 'flex',
                        flexDirection: 'column',
                        gap: '0.3rem',
                        padding: '0.6rem 0.7rem',
                        border: `1px solid ${current ? 'var(--cb-accent)' : 'var(--cb-rule)'}`,
                        borderRadius: '3px',
                        background: current ? 'var(--cb-accent-soft)' : 'var(--cb-paper-raised)',
                        minWidth: 0
                      },
                      children: [
                        jsxs('div', {
                          style: { display: 'flex', flexWrap: 'wrap', alignItems: 'baseline', gap: '0.3rem 0.6rem' },
                          children: [
                            jsx('h3', {
                              style: {
                                margin: 0,
                                fontFamily: CB_SERIF,
                                fontSize: CB_TYPE.lead,
                                fontWeight: 600,
                                color: 'var(--cb-ink)',
                                overflowWrap: 'anywhere'
                              },
                              children: `${row.pack_id} · v${row.pack_version}`
                            }),
                            jsx('span', {
                              style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' },
                              children: `${row.state} · ${row.source} · ${plural(row.file_count, 'file', 'files')}`
                            })
                          ]
                        }),
                        jsx('p', {
                          style: {
                            margin: 0,
                            fontFamily: CB_SANS,
                            fontSize: CB_TYPE.caption,
                            color: 'var(--cb-ink-soft)',
                            overflowWrap: 'anywhere'
                          },
                          children: `${row.license && row.license.id ? row.license.id : 'licence unspecified'} · ${row.content_hash}`
                        }),
                        current && preview
                          ? preview.error
                            ? jsx('p', {
                                style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-coral)' },
                                children: `Inspection refused: ${describeError(preview.error)}`
                              })
                            : jsxs('div', {
                                'data-cb-workshop-ledger-preview': '',
                                style: { display: 'flex', flexDirection: 'column', gap: '0.2rem' },
                                children: [
                                  jsx('p', {
                                    style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink)' },
                                    children: preview.integrity.hashes_match
                                      ? 'Integrity verified now: every declared file matches its hash.'
                                      : 'Hashes do not match now; the pack drifted from its manifest.'
                                  }),
                                  jsx('p', {
                                    style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' },
                                    children: `Trust labels: ${(preview.trust.labels || []).join(', ') || 'none recorded'}`
                                  })
                                ]
                              })
                          : jsx(CbAction, {
                              variant: 'tertiary',
                              className: 'self-start',
                              onClick: () => open(row),
                              'aria-expanded': current ? 'true' : 'false',
                              children: current ? 'Re-check the pack' : 'Inspect this version',
                              'aria-label': `Inspect ${row.pack_id} version ${row.pack_version}`
                            })
                      ]
                    }, rowKey)
                  })
                ]
              })
    ]
  })
}

/**
 * The destination. Three surfaces, one read of the catalogue, and the Library tab is the same
 * installed-pack shelf and import flow the route already had — moved under the Workshop so there is
 * one shelf, not two.
 */
function WorkshopView({ implemented, createOpen, onOpenCourse, onStartSyllabus, onStartImport, canSyllabus, canImport, onEmptyChange }) {
  const [tab, setTab] = useState('discover')
  const [selectedId, setSelectedId] = useState(null)
  const [installBusy, setInstallBusy] = useState(null)
  const [notice, setNotice] = useState(null)
  const width = useCbViewportWidth()
  const layout = cbLayoutFor(width)
  const motion = useCbMotion()
  const [prefs, toggleFavorite, setCategory] = useCbWorkshopPrefs()
  const catalog = useWorkshopCatalog(true)
  const items = catalog.data && Array.isArray(catalog.data.items) ? catalog.data.items : []
  const selected = selectedId ? items.find((item) => item.pack_id === selectedId) || null : null

  const onOpen = useCallback((item, options) => {
    if (options && options.continue) {
      openInstalled(item)
      return
    }
    setSelectedId(item.pack_id)
  }, [])

  const back = useCallback(() => {
    const packId = selectedId
    setSelectedId(null)
    if (!packId || typeof document === 'undefined') return
    window.setTimeout(() => {
      const node = document.querySelector(`[data-cb-workshop-open="${packId}"]`)
      if (node && typeof node.focus === 'function') node.focus({ preventScroll: true })
    }, 0)
  }, [selectedId])

  const openInstalled = useCallback(
    async (item) => {
      const courseId = item && item.installed && item.installed.course_id
      if (!courseId) {
        setNotice({ kind: 'warning', message: 'That pack is not in your library yet.' })
        return
      }
      const response = await rpc('library.list', { filter: 'all', limit: 100, sort: 'recent' })
      const rows = response && response.ok && response.result && Array.isArray(response.result.items) ? response.result.items : []
      const row = rows.find((candidate) => candidate.course_id === courseId)
      if (!row) {
        setNotice({ kind: 'warning', message: 'The library row for this pack could not be read. Reload the Library tab.' })
        return
      }
      setNotice(null)
      onOpenCourse(row)
    },
    [onOpenCourse]
  )

  const install = useCallback(
    async (item) => {
      setInstallBusy(item.pack_id)
      setNotice(null)
      try {
        const response = await rest('/workshop/install', { method: 'POST', body: { pack_id: item.pack_id } })
        if (!response || response.ok !== true) {
          setNotice({
            kind: 'warning',
            message: `${(response && response.code) || 'WORKSHOP_REFUSED'}: ${(response && response.message) || 'The pack could not be added.'}`
          })
          return
        }
        setNotice({
          kind: 'success',
          packId: item.pack_id,
          title: item.title,
          courseId: response.course_id,
          imported: response.imported,
          message: response.imported
            ? 'Added to your library. The course is open in Courses and the pack is installed on this profile.'
            : response.message || 'This pack is already in your library; nothing was imported twice.'
        })
        catalog.reload()
      } catch (error) {
        setNotice({ kind: 'warning', message: `HOST_UNAVAILABLE: ${describeError(error)}` })
      } finally {
        setInstallBusy(null)
      }
    },
    [catalog]
  )

  const onFavorite = useCallback(
    (item) => {
      toggleFavorite(item.pack_id)
    },
    [toggleFavorite]
  )

  const onCategory = useCallback(
    (item, category) => {
      setCategory(item.pack_id, category)
    },
    [setCategory]
  )

  let body
  if (tab === 'library') {
    body = jsxs('div', {
      'data-cb-workshop-library': '',
      style: { display: 'flex', flexDirection: 'column', gap: '0.75rem', minWidth: 0 },
      children: [
        jsxs('div', {
          'data-cb-workshop-library-actions': '',
          style: { display: 'flex', flexWrap: 'wrap', gap: '0.5rem', justifyContent: 'flex-end' },
          children: [
            canSyllabus
              ? jsx(CbAction, { variant: 'secondary', onClick: onStartSyllabus, children: SYLLABUS_COPY.action })
              : null,
            canImport
              ? jsx(CbAction, { variant: 'primary', onClick: onStartImport, children: 'Import pack' })
              : null
          ]
        }),
        jsx(LibraryView, {
          implemented,
          createOpen,
          onOpen: onOpenCourse,
          onStartSyllabus,
          onStartImport,
          onEmptyChange
        })
      ]
    })
  } else if (tab === 'provenance') {
    body = jsx(WorkshopProvenance, { implemented, motion, layout })
  } else if (selected) {
    body = jsx(WorkshopDetail, {
      item: selected,
      layout,
      motion,
      onBack: back,
      onInstall: install,
      onContinue: openInstalled,
      busy: installBusy === selected.pack_id,
      favorite: prefs.favorites.indexOf(selected.pack_id) >= 0,
      onFavorite,
      userCategory: (prefs.categories || {})[selected.pack_id] || null,
      onCategory
    })
  } else if (catalog.status === 'loading' && !catalog.data) {
    body = jsx('div', { className: 'py-8', children: jsx(sdk.Loader, { label: 'Reading the Workshop catalogue' }) })
  } else if (catalog.status === 'error') {
    body = jsxs('div', {
      'data-cb-workshop-error': (catalog.error && catalog.error.code) || 'WORKSHOP_UNAVAILABLE',
      style: { display: 'flex', flexDirection: 'column', gap: '0.6rem', maxWidth: CB_MEASURE },
      children: [
        jsx('h2', {
          style: workshopStateHeadingStyle,
          children: 'The Workshop could not be read'
        }),
        jsx('p', {
          style: workshopStateBodyStyle,
          children: `${(catalog.error && catalog.error.code) || 'WORKSHOP_UNAVAILABLE'}: ${(catalog.error && catalog.error.message) || 'The catalogue did not answer.'}`
        }),
        jsx(CbAction, { variant: 'tertiary', onClick: catalog.reload, className: 'self-start', children: 'Try again' })
      ]
    })
  } else if (!items.length) {
    body = jsxs('div', {
      'data-cb-workshop-empty': '',
      style: { display: 'flex', flexDirection: 'column', gap: '0.6rem', maxWidth: CB_MEASURE },
      children: [
        jsx('h2', { style: workshopStateHeadingStyle, children: 'No packs in this build' }),
        jsx('p', {
          style: workshopStateBodyStyle,
          children:
            'The Workshop ships with the packs this build bundles. If the catalogue is empty, nothing was installed and no pack is being offered.'
        })
      ]
    })
  } else {
    body = jsx(WorkshopDiscover, {
      catalog: catalog.data,
      layout,
      motion,
      prefs,
      onOpen,
      onInstall: install,
      busyInstall: installBusy,
      onFavorite,
      onOpenCourse: openInstalled
    })
  }

  return jsxs('div', {
    'data-cb-workshop': tab,
    style: { display: 'flex', flexDirection: 'column', gap: '1rem', minWidth: 0 },
    children: [
      jsx('nav', {
        'data-cb-workshop-tabs': '',
        'aria-label': 'Workshop surfaces',
        style: { display: 'flex', flexWrap: 'wrap', gap: '0.25rem 1.25rem', borderBottom: '1px solid var(--cb-rule)' },
        children: WORKSHOP_TABS.map((entry) =>
          jsx('button', {
            type: 'button',
            'data-cb-workshop-tab': entry.id,
            'aria-current': tab === entry.id ? 'page' : undefined,
            onClick: () => {
              setTab(entry.id)
              setSelectedId(null)
            },
            style: {
              background: 'none',
              border: 'none',
              borderBottom: `2px solid ${tab === entry.id ? 'var(--cb-lamp)' : 'transparent'}`,
              padding: '0.5rem 0',
              minHeight: '44px',
              fontFamily: CB_SANS,
              fontSize: CB_TYPE.meta,
              fontWeight: tab === entry.id ? 600 : 400,
              color: tab === entry.id ? 'var(--cb-ink)' : 'var(--cb-ink-soft)',
              cursor: tab === entry.id ? 'default' : 'pointer'
            },
            children: entry.label
          }, entry.id)
        )
      }),
      catalog.data && catalog.data.refused && catalog.data.refused.length
        ? jsxs('div', {
            'data-cb-workshop-refused': '',
            role: 'status',
            style: {
              display: 'flex',
              flexDirection: 'column',
              gap: '0.2rem',
              padding: '0.5rem 0.65rem',
              border: '1px solid var(--cb-coral)',
              borderRadius: '3px',
              background: 'var(--cb-paper-raised)'
            },
            children: [
              jsx('p', {
                style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, fontWeight: 600, color: 'var(--cb-coral)' },
                children: `${plural(catalog.data.refused.length, 'pack', 'packs')} could not be verified and are not shown`
              }),
              ...catalog.data.refused.map((entry) =>
                jsx('p', {
                  style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)', overflowWrap: 'anywhere' },
                  children: `${entry.pack_id}: ${entry.reason}`
                }, `refused-${entry.pack_id}`)
              )
            ]
          })
        : null,
      notice
        ? jsxs('div', {
            'data-cb-workshop-notice': notice.kind,
            role: 'status',
            'aria-live': 'polite',
            style: {
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: '0.5rem',
              padding: '0.65rem 0.8rem',
              border: `1px solid ${notice.kind === 'success' ? 'var(--cb-field)' : 'var(--cb-coral)'}`,
              borderRadius: '3px',
              background: 'var(--cb-paper-raised)'
            },
            children: [
              jsxs('div', {
                style: { display: 'flex', flexDirection: 'column', gap: '0.15rem', minWidth: 0 },
                children: [
                  jsx('p', {
                    style: {
                      margin: 0,
                      fontFamily: CB_SANS,
                      fontSize: CB_TYPE.meta,
                      fontWeight: 600,
                      color: notice.kind === 'success' ? 'var(--cb-field)' : 'var(--cb-coral)'
                    },
                    children: notice.kind === 'success' ? `Added: ${notice.title}` : 'Not added'
                  }),
                  jsx('p', {
                    style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' },
                    children: notice.message
                  })
                ]
              }),
              jsxs('div', {
                style: { display: 'flex', flexWrap: 'wrap', gap: '0.4rem' },
                children: [
                  notice.courseId
                    ? jsx(CbAction, {
                        variant: 'secondary',
                        onClick: () => {
                          const item = items.find((entry) => entry.pack_id === notice.packId)
                          if (item) openInstalled(item)
                        },
                        children: 'Open the course'
                      })
                    : null,
                  jsx(CbAction, { variant: 'tertiary', onClick: () => setNotice(null), children: 'Dismiss' })
                ]
              })
            ]
          })
        : null,
      body
    ]
  })
}


/* ── GM-004: the course world and the World Studio ─────────────────────────────────────────
 * A world is a governed visual kit: textless plates plus a style specification. Everything a
 * learner reads here is authored DOM copy; the image model never supplies type, a number, a
 * rating or a procedure. The studio's states are driven by `world.read`, and every primary
 * action names the fact it needs next (a plan, a style choice, the kit, a final approval).
 */

const CB_WORLD_COPY = Object.freeze({
  label: 'Course world',
  hero: 'World',
  modeGame: 'Game',
  modeTextbook: 'Textbook',
  changeMode: 'Change mode',
  courseSettings: 'Course settings',
  notApprovedTitle: 'World not approved yet',
  notApprovedBody:
    'This course reads as Textbook until its world is approved. Your lessons and plan are unchanged.',
  openStudio: 'Open World Studio',
  readFallback: 'Use Textbook mode',
  readUnsupported: 'This backend does not report a course world yet.',
  readError: 'The course world could not be read',
  plateMissing: 'The art for this plate is not available; the text label stands in for it.'
})

/** One authored name per policy grammar. The board's own `label` is the policy word, never art. */
const CB_GRAMMAR_NAME = Object.freeze({
  field_atlas: 'Field atlas',
  workshop_manual: 'Workshop manual',
  observatory: 'Observatory',
  kitchen_table: 'Kitchen table',
  archive_desk: 'Archive desk',
  studio_bench: 'Studio bench',
  lab_bench: 'Lab bench',
  instrument_board: 'Instrument board'
})

const CB_GRAMMAR_ONE_LINE = Object.freeze({
  field_atlas: 'Maps, lanterns and a field notebook — a place to travel through the subject.',
  workshop_manual: 'A service bay, tool wall and manual pages — orientation beside the procedure.',
  observatory: 'Star charts, instruments and an observation log.',
  kitchen_table: 'A work surface, ingredient cards and a recipe board.',
  archive_desk: 'Documents, stamps, maps and index cards.',
  studio_bench: 'Materials, swatches and a sketchbook.',
  lab_bench: 'Glassware, a lab notebook and labelled stations.',
  instrument_board: 'Instruments, graph paper and a blackboard.'
})

const CB_WORLD_STATE_WORD = Object.freeze({
  not_requested: 'Not started',
  concepts_generating: 'Choosing directions',
  concepts_ready: 'Three directions',
  style_selected: 'Direction chosen',
  kit_generating: 'Building the world',
  kit_ready: 'Ready to approve',
  approved: 'Approved',
  failed: 'Could not finish',
  unavailable: 'Unavailable'
})

function cbWorldStateWord(state) {
  return CB_WORLD_STATE_WORD[state] || CB_WORLD_STATE_WORD.not_requested
}

/** The plate for one role. `section` is matched by its section id, never by index. */
function cbWorldPlate(assets, role, sectionId) {
  const list = Array.isArray(assets) ? assets : []
  if (role === 'section') {
    return list.find((item) => item && item.role === 'section' && item.section_id === sectionId) || null
  }
  return list.find((item) => item && item.role === role) || null
}

/** Sections the world actually has art for, in the plate's own order. */
function cbWorldSectionPlates(world) {
  const assets = (world && world.assets) || []
  const brief = (world && world.brief) || {}
  const byId = new Map((brief.sections || []).map((section) => [section.id, section.title || '']))
  return assets
    .filter((item) => item && item.role === 'section' && item.section_id)
    .map((item) => ({
      section_id: item.section_id,
      section_key: item.section_key || item.section_id,
      title: byId.get(item.section_id) || '',
      artifact_id: item.artifact_id
    }))
}

/** The named roles still missing from a kit: `hero`, `cover` or `section:<id>`. */
function cbWorldMissingRoles(world) {
  const error = world && world.error
  if (error && Array.isArray(error.missing_roles)) return error.missing_roles
  return []
}

/** Whether a world counts as final-approved for the Game gate. Never inferred from a style. */
function cbWorldApproved(world) {
  return Boolean(world && world.state === 'approved' && world.approved_hash)
}

/**
 * `world.read` for one course. A failed or unsupported read is its own state: the shelf and the
 * course home name the failed read instead of printing a mode nobody answered.
 */
function useWorldRead(courseId, enabled) {
  const [state, setState] = useState({ status: 'idle', data: null, error: null })
  const [ticket, setTicket] = useState(0)
  const supported = Boolean(enabled && courseId && backendSupports('world.read'))
  const reload = useCallback(() => setTicket((value) => value + 1), [])
  useEffect(() => {
    if (!supported) {
      setState({ status: courseId ? 'unsupported' : 'idle', data: null, error: null })
      return undefined
    }
    let live = true
    setState((previous) => ({
      status: previous.data ? 'ready' : 'loading',
      data: previous.data,
      error: null
    }))
    rpc('world.read', { course_id: courseId })
      .then((response) => {
        if (!live) return
        if (response && response.ok && response.result) {
          setState({ status: 'ready', data: response.result, error: null })
        } else {
          setState({ status: 'error', data: null, error: (response && response.error) || null })
        }
      })
      .catch((error) => {
        if (live) setState({ status: 'error', data: null, error })
      })
    return () => {
      live = false
    }
  }, [courseId, supported, ticket])
  return { ...state, reload }
}

/**
 * One textless plate. The artifact route is the only image source; when it refuses, the plate
 * paints its authored caption instead of an invented picture or a broken-image icon.
 */
function WorldPlate({ artifactId, caption, height, kind }) {
  const preview = useArtifactPreview(artifactId)
  const frame = {
    position: 'relative',
    width: '100%',
    height: height || '11rem',
    background: 'var(--cb-paper-raised)',
    border: '1px solid var(--cb-rule)',
    borderRadius: '2px',
    overflow: 'hidden',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center'
  }
  if (preview.state === 'ready' && preview.mime && preview.mime.startsWith('image/')) {
    return jsxs('div', {
      'data-cb-world-plate': kind || 'orientation',
      'data-cb-world-plate-artifact': artifactId,
      style: frame,
      children: [
        jsx('img', {
          'data-cb-world-plate-art': '',
          alt: caption,
          src: preview.data_url,
          loading: 'lazy',
          style: { width: '100%', height: '100%', objectFit: 'cover', display: 'block' }
        }),
        jsx('span', {
          'aria-hidden': 'true',
          style: {
            position: 'absolute',
            left: 0,
            right: 0,
            bottom: 0,
            padding: '0.25rem 0.5rem',
            fontFamily: CB_SANS,
            fontSize: CB_TYPE.caption,
            color: 'var(--cb-ink-soft)',
            background: 'var(--cb-paper)',
            borderTop: '1px solid var(--cb-rule)'
          },
          children: caption
        })
      ]
    })
  }
  return jsx('div', {
    'data-cb-world-plate': kind || 'orientation',
    'data-cb-world-plate-state': preview.state,
    style: { ...frame, padding: '0.6rem' },
    children: jsxs('div', {
      style: { display: 'flex', flexDirection: 'column', gap: '0.2rem', textAlign: 'center' },
      children: [
        jsx('span', {
          style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, color: 'var(--cb-ink)' },
          children: caption
        }),
        jsx('span', {
          style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' },
          children: preview.state === 'loading' ? 'Loading the plate' : CB_WORLD_COPY.plateMissing
        })
      ]
    })
  })
}

/** The durable mode badge. It is a word, never a colour-only signal, and it is not a control. */
function ModeBadge({ mode, pending }) {
  const game = mode === 'game'
  return jsx('span', {
    'data-cb-mode-badge': mode || 'textbook',
    style: {
      display: 'inline-flex',
      alignItems: 'center',
      gap: '0.3rem',
      padding: '0.1rem 0.45rem',
      border: `1px solid ${game ? 'var(--cb-ochre)' : 'var(--cb-accent)'}`,
      borderRadius: '2px',
      fontFamily: CB_SANS,
      fontSize: CB_TYPE.caption,
      fontWeight: 600,
      color: game ? 'var(--cb-ochre)' : 'var(--cb-accent)',
      background: 'var(--cb-paper)'
    },
    children: [
      jsx('span', {
        'aria-hidden': 'true',
        style: {
          width: '0.4rem',
          height: '0.4rem',
          borderRadius: '999px',
          background: game ? 'var(--cb-ochre)' : 'var(--cb-accent)'
        }
      }),
      game ? CB_WORLD_COPY.modeGame : CB_WORLD_COPY.modeTextbook,
      pending ? ' · saving' : null
    ]
  })
}

/**
 * The course-home world: a hero plate with real DOM type over a quiet field, then the route's
 * section cards. Only an approved Game world paints here; a Textbook course has no world surface.
 */
function CourseWorldHero({ world, mode, sectionPlates, narrow, onOpenStudio, onOpenSection }) {
  const approved = cbWorldApproved(world)
  const hero = cbWorldPlate(world && world.assets, 'hero')
  const title = ((world && world.brief && world.brief.title) || '').trim()
  const grammar = world && world.selected_concept_id
    ? String(world.selected_concept_id).split('--').pop()
    : null
  const grammarName = (grammar && CB_GRAMMAR_NAME[grammar]) || null
  if (!approved) {
    return jsxs('section', {
      'data-cb-world': 'unapproved',
      'data-cb-world-state': (world && world.state) || 'not_requested',
      style: {
        display: 'flex',
        flexDirection: 'column',
        gap: '0.5rem',
        padding: '0.9rem 1rem 1rem',
        background: 'var(--cb-paper-raised)',
        border: '1px solid var(--cb-rule)',
        borderTop: '3px solid var(--cb-ochre)',
        borderRadius: '2px',
        minWidth: 0
      },
      children: [
        jsxs('div', {
          style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '0.5rem' },
          children: [jsx(ModeBadge, { mode }), jsx('span', {
            style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, fontWeight: 600, color: 'var(--cb-ink)' },
            children: CB_WORLD_COPY.notApprovedTitle
          })]
        }),
        jsx('p', {
          style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.5, color: 'var(--cb-ink-soft)', maxWidth: '58ch' },
          children: CB_WORLD_COPY.notApprovedBody
        }),
        jsx(CbAction, {
          variant: 'secondary',
          'data-cb-world-open-studio': '',
          onClick: onOpenStudio,
          style: { alignSelf: 'flex-start' },
          children: CB_WORLD_COPY.openStudio
        })
      ]
    })
  }
  return jsxs('section', {
    'data-cb-world': 'game',
    'data-cb-world-approved': world.approved_hash,
    style: { display: 'flex', flexDirection: 'column', gap: '0.75rem', minWidth: 0 },
    children: [
      jsxs('div', {
        'data-cb-world-hero': '',
        style: {
          display: 'grid',
          gridTemplateColumns: narrow ? 'minmax(0, 1fr)' : 'minmax(0, 1fr) 13.25rem',
          gap: '0.9rem',
          padding: '0.9rem 1rem 1rem',
          background: 'var(--cb-lamp-soft)',
          borderTop: '3px solid var(--cb-lamp)',
          borderRadius: '2px',
          minWidth: 0
        },
        children: [
          jsxs('div', {
            style: { display: 'flex', flexDirection: 'column', gap: '0.35rem', minWidth: 0, justifyContent: 'center' },
            children: [
              jsxs('div', {
                style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '0.45rem' },
                children: [
                  jsx('span', {
                    style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--cb-ink-soft)' },
                    children: CB_WORLD_COPY.label
                  }),
                  jsx(ModeBadge, { mode })
                ]
              }),
              jsx('h2', {
                'data-cb-world-title': '',
                style: {
                  margin: 0,
                  fontFamily: CB_SERIF,
                  fontSize: CB_TYPE.heading,
                  fontWeight: 600,
                  lineHeight: 1.15,
                  color: 'var(--cb-ink)',
                  minWidth: 0,
                  overflowWrap: 'anywhere'
                },
                children: title || 'This course'
              }),
              grammarName
                ? jsx('div', {
                    'data-cb-world-grammar': '',
                    style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, color: 'var(--cb-ink-soft)' },
                    children: grammarName
                  })
                : null,
              jsx(CbAction, {
                variant: 'tertiary',
                'data-cb-world-change': '',
                onClick: onOpenStudio,
                style: { alignSelf: 'flex-start' },
                children: 'Review the world'
              })
            ]
          }, 'type'),
          jsx(WorldPlate, {
            artifactId: hero ? hero.artifact_id : null,
            caption: CB_WORLD_COPY.hero,
            height: '8.5rem',
            kind: 'hero'
          }, 'hero')
        ]
      }, 'hero'),
      sectionPlates.length
        ? jsx('div', {
            'data-cb-world-route': '',
            role: 'list',
            style: {
              display: 'grid',
              gridTemplateColumns: narrow ? 'minmax(0, 1fr)' : 'repeat(auto-fit, minmax(min(100%, 12rem), 1fr))',
              gap: '0.6rem',
              minWidth: 0
            },
            children: sectionPlates.map((plate) => {
              const card = jsxs('span', {
                style: { display: 'flex', flexDirection: 'column', gap: '0.3rem', minWidth: 0, width: '100%', textAlign: 'left', font: 'inherit' },
                children: [
                  jsx(WorldPlate, { artifactId: plate.artifact_id, caption: plate.title || plate.section_key, height: '6.5rem', kind: 'section' }),
                  jsx('span', {
                    'data-cb-world-section-title': plate.section_id,
                    style: { fontFamily: CB_SERIF, fontSize: CB_TYPE.body, fontWeight: 600, color: 'var(--cb-ink)', lineHeight: 1.3 },
                    children: plate.title || 'Section'
                  })
                ]
              })
              if (!onOpenSection) {
                return jsx('div', { role: 'listitem', 'data-cb-world-section': plate.section_id, style: { minWidth: 0 } }, plate.section_id)
              }
              return jsx('button', {
                type: 'button',
                role: 'listitem',
                'data-cb-world-section': plate.section_id,
                onClick: () => onOpenSection(plate.section_id),
                style: {
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '0.3rem',
                  minWidth: 0,
                  padding: 0,
                  border: 'none',
                  background: 'transparent',
                  color: 'inherit',
                  cursor: 'pointer',
                  textAlign: 'left',
                  font: 'inherit'
                },
                children: card
              }, plate.section_id)
            })
          })
        : null
    ]
  })
}

/**
 * The World Studio. It is a step in a course's setup, never a top-level destination, and every
 * state has exactly one primary action. It never renders generated text: the concept `label` is
 * the policy's authored grammar word, the palette chips are swatches only, and a plate is art.
 */
function WorldStudio({ courseId, mode, world, worldStatus, worldError, onReload, onClose, onChanged, autoStart }) {
  const [busy, setBusy] = useState(null)
  const [jobId, setJobId] = useState(null)
  const [job, setJob] = useState(null)
  const [error, setError] = useState(null)
  const [direction, setDirection] = useState({ tone: '', audience: '', include: '', avoid: '' })
  const [editing, setEditing] = useState(false)
  const [reasonOpen, setReasonOpen] = useState(false)
  const width = useCbViewportWidth()
  const narrow = width > 0 && width < 720
  const state = (world && world.state) || 'not_requested'
  const revision = world ? world.revision : 0
  const missing = cbWorldMissingRoles(world)
  const providerUnavailable = Boolean(
    world && (state === 'unavailable' || (world.error && world.error.reason === 'provider_unavailable'))
  )

  // A generation is a real media job. Poll its own state; on a terminal answer re-read the world
  // instead of guessing what was produced.
  useEffect(() => {
    if (!jobId) return undefined
    let live = true
    let tries = 0
    const poll = async () => {
      tries += 1
      const response = await rpc('jobs.get', { job_id: jobId })
      if (!live) return
      const row = response && response.ok && response.result ? response.result.job : null
      if (!row) return
      setJob(row)
      const finished = ['succeeded', 'done', 'failed', 'cancelled', 'interrupted_requires_retry'].includes(row.state)
      if (!finished && tries < 120) return
      setJobId(null)
      setBusy(null)
      if (row.state === 'failed' || row.state === 'cancelled') {
        setError({
          code: 'WORLD_JOB_' + String(row.state).toUpperCase(),
          message: (row.error && (row.error.message || row.error.reason)) || 'The world job did not finish.'
        })
      }
      onReload()
    }
    const handle = setInterval(poll, 1200)
    poll()
    return () => {
      live = false
      clearInterval(handle)
    }
  }, [jobId])

  const patch = useCallback(() => {
    const value = {}
    if (direction.tone.trim()) value.tone = direction.tone.trim()
    if (direction.audience.trim()) value.audience = direction.audience.trim()
    const motifs = direction.include.split(',').map((item) => item.trim()).filter(Boolean).slice(0, 6)
    const forbidden = direction.avoid.split(',').map((item) => item.trim()).filter(Boolean).slice(0, 6)
    if (motifs.length) value.motifs = motifs
    if (forbidden.length) value.forbidden = forbidden
    return Object.keys(value).length ? value : null
  }, [direction])

  const generate = useCallback(async (stage, extra) => {
    if (busy) return
    setError(null)
    setBusy(stage)
    const payload = { course_id: courseId, stage, ...extra }
    const response = await rpc('world.generate', payload, {
      idempotencyKey: `cb-world-${stage}-${newOperationId('world')}`,
      expectedRevision: revision
    })
    if (!response || !response.ok) {
      setBusy(null)
      setError({
        code: (response && response.error && response.error.code) || 'HOST_UNAVAILABLE',
        message: describeError(response && response.error)
      })
      onReload()
      return
    }
    setJobId(response.result.job_id)
    setJob({ state: response.result.state, progress: { message: 'Queued' } })
    onReload()
  }, [busy, courseId, onReload, revision])

  const approveStyle = useCallback(async (concept) => {
    if (busy) return
    setError(null)
    setBusy('style')
    const response = await rpc('world.approve', {
      course_id: courseId,
      world_id: world.world_id,
      stage: 'style',
      approved_hash: concept.style_hash
    }, {
      idempotencyKey: `cb-world-style-${newOperationId('world')}`,
      expectedRevision: revision
    })
    setBusy(null)
    if (!response || !response.ok) {
      setError({ code: (response && response.error && response.error.code) || 'HOST_UNAVAILABLE', message: describeError(response && response.error) })
    }
    onReload()
  }, [busy, courseId, onReload, revision, world])

  const approveFinal = useCallback(async () => {
    if (busy) return
    setError(null)
    setBusy('final')
    const approved = await rpc('world.approve', {
      course_id: courseId,
      world_id: world.world_id,
      stage: 'final',
      approved_hash: world.kit_hash
    }, {
      idempotencyKey: `cb-world-final-${newOperationId('world')}`,
      expectedRevision: revision
    })
    if (!approved || !approved.ok) {
      setBusy(null)
      setError({ code: (approved && approved.error && approved.error.code) || 'HOST_UNAVAILABLE', message: describeError(approved && approved.error) })
      onReload()
      return
    }
    // Final visual approval is the gate: the same press is what lets the course enter Game mode.
    if (mode !== 'game') {
      const nextRevision = (approved.result.world && approved.result.world.revision) || revision + 1
      const switched = await rpc('course.mode.set', { course_id: courseId, mode: 'game' }, {
        idempotencyKey: `cb-mode-game-${newOperationId('world')}`,
        expectedRevision: nextRevision
      })
      if (!switched || !switched.ok) {
        setBusy(null)
        setError({
          code: (switched && switched.error && switched.error.code) || 'HOST_UNAVAILABLE',
          message:
            'The world is approved, but the course could not switch to Game mode: ' +
            describeError(switched && switched.error)
        })
        onReload()
        if (onChanged) onChanged()
        return
      }
    }
    setBusy(null)
    if (onChanged) onChanged()
    onReload()
  }, [busy, courseId, mode, onChanged, onReload, revision, world])

  const concepts = (world && Array.isArray(world.concepts)) ? world.concepts : []
  const sectionPlates = cbWorldSectionPlates(world)
  const hero = cbWorldPlate(world && world.assets, 'hero')
  const cover = cbWorldPlate(world && world.assets, 'cover')

  // The Textbook → Game prompt promises generation, so arriving from that dialog starts the
  // concept job once. It is not a background job: the learner is on the screen that shows it.
  useEffect(() => {
    if (!autoStart) return
    if (worldStatus !== 'ready') return
    if (state !== 'not_requested' || busy || jobId) return
    generate('concepts', { brief_patch: patch() })
    // Only the first mount of an untouched world starts a job.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoStart, worldStatus, state])

  if (worldStatus === 'unsupported') {
    return jsx(WorldStudioFrame, {
      onClose,
      state: 'unsupported',
      children: jsx(sdk.EmptyState, {
        title: 'This backend does not carry the world wire yet',
        description: CB_WORLD_COPY.readUnsupported + ' Your course stays in Textbook mode and no art is generated.',
        children: jsx(CbAction, { variant: 'primary', onClick: onClose, children: 'Keep Textbook' })
      })
    })
  }
  if (worldStatus === 'error') {
    return jsx(WorldStudioFrame, {
      onClose,
      state: 'error',
      children: jsxs(sdk.ErrorState, {
        title: 'The course world could not be read',
        description: describeError(worldError),
        children: [
          jsx(CbAction, { variant: 'primary', onClick: onReload, children: 'Try again' }),
          jsx(CbAction, { variant: 'tertiary', onClick: onClose, children: 'Back to the course' })
        ]
      })
    })
  }
  if (worldStatus === 'loading' && !world) {
    return jsx(WorldStudioFrame, {
      onClose,
      state: 'loading',
      children: jsxs('div', {
        style: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.5rem', padding: '2rem 0' },
        children: [
          jsx(sdk.Loader, { label: 'Reading the course world' }),
          jsx('p', { style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, color: 'var(--cb-ink-soft)' }, children: 'Nothing already saved is lost.' })
        ]
      })
    })
  }

  const generating = Boolean(jobId) || state === 'concepts_generating' || state === 'kit_generating'
  const stageMessage = (job && job.progress && job.progress.message) || cbWorldStateWord(state)

  const body = []
  body.push(jsxs('div', {
    'data-cb-world-studio-head': '',
    style: { display: 'flex', flexDirection: 'column', gap: '0.3rem', minWidth: 0 },
    children: [
      jsxs('div', {
        style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '0.5rem' },
        children: [
          jsx('span', {
            style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--cb-ink-soft)' },
            children: CB_WORLD_COPY.label
          }),
          jsx(ModeBadge, { mode })
        ]
      }),
      jsx('h2', {
        id: 'cb-world-studio-title',
        style: { margin: 0, fontFamily: CB_SERIF, fontSize: CB_TYPE.heading, fontWeight: 600, lineHeight: 1.15, color: 'var(--cb-ink)' },
        children: 'Choose the world for this course'
      }),
      jsx('p', {
        style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.5, color: 'var(--cb-ink-soft)', maxWidth: '58ch' },
        children: (world && world.brief && world.brief.end_capability) || 'The world is orientation art. Your lessons, checks and evidence are unchanged by it.'
      })
    ]
  }, 'head'))

  if (error) {
    body.push(jsxs('div', {
      'data-cb-world-error': error.code || 'ERROR',
      role: 'alert',
      style: {
        display: 'flex',
        flexDirection: 'column',
        gap: '0.35rem',
        padding: '0.6rem 0.75rem',
        background: 'var(--cb-paper-raised)',
        borderLeft: '2px solid var(--cb-coral)',
        minWidth: 0
      },
      children: [
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, fontWeight: 600, color: 'var(--cb-coral)' }, children: 'That did not finish' }),
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.5, color: 'var(--cb-ink)' }, children: error.message })
      ]
    }, 'error'))
  }

  if (providerUnavailable) {
    body.push(jsxs('div', {
      'data-cb-world-provider': 'unavailable',
      style: { display: 'flex', flexDirection: 'column', gap: '0.5rem', padding: '0.75rem 0.85rem', background: 'var(--cb-paper-raised)', borderTop: '3px solid var(--cb-ochre)', minWidth: 0 },
      children: [
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, fontWeight: 600, color: 'var(--cb-ink)' }, children: 'Game mode is unavailable because image generation is not configured.' }),
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.5, color: 'var(--cb-ink-soft)' }, children: 'The course stays in Textbook mode and your lessons are unchanged. No fake world is created.' })
      ]
    }, 'provider'))
  }

  if (state === 'failed' && missing.length) {
    body.push(jsxs('div', {
      'data-cb-world-partial': missing.join(','),
      style: { display: 'flex', flexDirection: 'column', gap: '0.4rem', padding: '0.75rem 0.85rem', background: 'var(--cb-paper-raised)', borderTop: '3px solid var(--cb-coral)', minWidth: 0 },
      children: [
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, fontWeight: 600, color: 'var(--cb-ink)' }, children: 'Some plates are missing' }),
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.5, color: 'var(--cb-ink-soft)' }, children: `Missing: ${missing.join(', ')}. Nothing is approved until every role exists, and no placeholder art is saved.` })
      ]
    }, 'partial'))
  }

  // Three directions, or the chosen one. Boards are art plus an authored name and a palette strip.
  if ((state === 'concepts_ready' || state === 'style_selected') && concepts.length) {
    body.push(jsx('div', {
      'data-cb-world-concepts': String(concepts.length),
      role: 'list',
      style: {
        display: 'grid',
        gridTemplateColumns: narrow ? 'minmax(0, 1fr)' : 'repeat(auto-fit, minmax(min(100%, 15rem), 1fr))',
        gap: '0.7rem',
        minWidth: 0
      },
      children: concepts.map((concept) => {
        const selected = world.selected_concept_id === concept.style_id
        const grammar = String(concept.style_id).split('--').pop()
        const name = CB_GRAMMAR_NAME[concept.label] || CB_GRAMMAR_NAME[grammar] || 'Direction'
        const one = CB_GRAMMAR_ONE_LINE[concept.label] || CB_GRAMMAR_ONE_LINE[grammar] || ''
        return jsxs('div', {
          role: 'listitem',
          'data-cb-world-concept': concept.style_id,
          'data-cb-world-concept-selected': selected ? 'true' : 'false',
          style: {
            display: 'flex',
            flexDirection: 'column',
            gap: '0.4rem',
            padding: '0.6rem',
            minWidth: 0,
            background: 'var(--cb-paper-raised)',
            border: selected ? '2px solid var(--cb-lamp)' : '1px solid var(--cb-rule)',
            borderRadius: '2px'
          },
          children: [
            jsx(WorldPlate, { artifactId: concept.artifact_id, caption: name, height: '8rem', kind: 'concept' }),
            jsx('span', { style: { fontFamily: CB_SERIF, fontSize: CB_TYPE.lead, fontWeight: 600, color: 'var(--cb-ink)' }, children: name }),
            one ? jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.5, color: 'var(--cb-ink-soft)' }, children: one }) : null,
            jsxs('span', {
              'data-cb-world-palette': concept.style_id,
              'aria-hidden': 'true',
              style: { display: 'flex', gap: '0.2rem' },
              children: (concept.palette || []).slice(0, 5).map((swatch, index) => jsx('span', {
                style: { width: '1rem', height: '0.75rem', background: swatch, border: '1px solid var(--cb-rule)' }
              }, String(index)))
            }),
            selected
              ? jsx('span', { 'data-cb-world-chosen': '', style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 600, color: 'var(--cb-ink)' }, children: 'Chosen direction' })
              : jsx('div', {
                  'data-cb-world-use-direction': concept.style_id,
                  'data-cb-world-primary': concept.style_id === (concepts[0] && concepts[0].style_id) ? 'direction' : undefined,
                  style: { display: 'inline-flex' },
                  children: jsx(CbAction, {
                    variant: concept.style_id === (concepts[0] && concepts[0].style_id) ? 'primary' : 'secondary',
                    disabled: Boolean(busy),
                    onClick: () => approveStyle(concept),
                    children: 'Use this direction'
                  })
                })
          ]
        }, concept.style_id)
      })
    }, 'concepts'))
  }

  if (state === 'kit_ready' && world.kit_hash) {
    body.push(jsxs('div', {
      'data-cb-world-kit': world.kit_hash,
      style: { display: 'flex', flexDirection: 'column', gap: '0.6rem', minWidth: 0 },
      children: [
        jsxs('div', {
          style: {
            display: 'grid',
            gridTemplateColumns: narrow ? 'minmax(0, 1fr)' : 'minmax(0, 1fr) 11rem',
            gap: '0.7rem',
            padding: '0.85rem 0.95rem',
            background: 'var(--cb-lamp-soft)',
            borderTop: '3px solid var(--cb-lamp)',
            minWidth: 0
          },
          children: [
            jsxs('div', {
              style: { display: 'flex', flexDirection: 'column', gap: '0.25rem', justifyContent: 'center', minWidth: 0 },
              children: [
                jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--cb-ink-soft)' }, children: 'The world you would get' }),
                jsx('span', { style: { fontFamily: CB_SERIF, fontSize: CB_TYPE.heading, fontWeight: 600, lineHeight: 1.15, color: 'var(--cb-ink)', overflowWrap: 'anywhere' }, children: (world.brief && world.brief.title) || 'This course' }),
                jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' }, children: `1 hero · 1 cover · ${sectionPlates.length} section ${sectionPlates.length === 1 ? 'card' : 'cards'}` })
              ]
            }),
            jsx(WorldPlate, { artifactId: cover ? cover.artifact_id : null, caption: 'Library cover', height: '7rem', kind: 'cover' })
          ]
        }),
        jsx('div', {
          style: { display: 'grid', gridTemplateColumns: narrow ? 'minmax(0, 1fr)' : 'repeat(auto-fit, minmax(min(100%, 9rem), 1fr))', gap: '0.5rem', minWidth: 0 },
          children: sectionPlates.map((plate) => jsx(WorldPlate, {
            artifactId: plate.artifact_id,
            caption: plate.title || 'Section card',
            height: '5.5rem',
            kind: 'section'
          }, plate.section_id))
        }),
        jsx('p', {
          style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.5, color: 'var(--cb-ink-soft)', maxWidth: '58ch' },
          children: mode === 'game'
            ? 'Use this world and the course opens on it. This is the final visual approval; you can review it again from Course settings.'
            : 'Use this world to approve the kit and switch this course to Game mode. Your lessons, checks and evidence do not change.'
        })
      ]
    }, 'kit'))
  }

  if (state === 'approved') {
    body.push(jsxs('div', {
      'data-cb-world-approved-panel': world.approved_hash,
      style: { display: 'flex', flexDirection: 'column', gap: '0.5rem', padding: '0.8rem 0.9rem', background: 'var(--cb-paper-raised)', borderTop: '3px solid var(--cb-field)', minWidth: 0 },
      children: [
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, fontWeight: 600, color: 'var(--cb-field)' }, children: 'This world is approved.' }),
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.5, color: 'var(--cb-ink-soft)' }, children: 'Changing it starts a new direction and leaves this approved kit on the course until you approve another.' })
      ]
    }, 'approved'))
  }

  // Edit direction: presentation-only fields, exactly the closed patch the backend accepts.
  body.push(jsxs('div', {
    'data-cb-world-direction': editing ? 'open' : 'closed',
    style: { display: 'flex', flexDirection: 'column', gap: '0.45rem', borderTop: '1px solid var(--cb-rule)', paddingTop: '0.6rem', minWidth: 0 },
    children: [
      jsx('button', {
        type: 'button',
        'data-cb-world-direction-toggle': '',
        onClick: () => setEditing((value) => !value),
        style: { alignSelf: 'flex-start', background: 'none', border: 'none', padding: 0, font: 'inherit', fontFamily: CB_SANS, fontSize: CB_TYPE.meta, fontWeight: 600, color: 'var(--cb-accent)', cursor: 'pointer', textDecoration: 'underline' },
        children: editing ? 'Close the direction' : 'Edit direction'
      }),
      editing
        ? jsxs('div', {
            style: { display: 'grid', gridTemplateColumns: narrow ? 'minmax(0, 1fr)' : 'repeat(2, minmax(0, 1fr))', gap: '0.5rem', minWidth: 0 },
            children: [
              worldField('Mood', 'cb-world-tone', direction.tone, (value) => setDirection((current) => ({ ...current, tone: value })), 'e.g. calm, practical'),
              worldField('Who it is for', 'cb-world-audience', direction.audience, (value) => setDirection((current) => ({ ...current, audience: value })), 'e.g. adult learner'),
              worldField('Motifs to include', 'cb-world-include', direction.include, (value) => setDirection((current) => ({ ...current, include: value })), 'comma separated'),
              worldField('Motifs to avoid', 'cb-world-avoid', direction.avoid, (value) => setDirection((current) => ({ ...current, avoid: value })), 'comma separated')
            ]
          }, 'fields')
        : null,
      editing
        ? jsx('p', {
            style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.5, color: 'var(--cb-ink-soft)' },
            children: 'These words steer the next generation only. They never edit a lesson, a check or a source.'
          })
        : null
    ]
  }, 'direction'))

  if (reasonOpen) {
    body.push(jsxs('div', {
      'data-cb-world-reason': '',
      style: { display: 'flex', flexDirection: 'column', gap: '0.4rem', padding: '0.6rem 0.75rem', background: 'var(--cb-paper-raised)', border: '1px solid var(--cb-rule)', minWidth: 0 },
      children: [
        jsx('label', {
          htmlFor: 'cb-world-reason-input',
          style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 600, color: 'var(--cb-ink)' },
          children: 'What should change?'
        }),
        jsx(sdk.Input, {
          id: 'cb-world-reason-input',
          value: direction.motifsNote || '',
          onChange: (event) => setDirection((current) => ({ ...current, motifsNote: event.target.value })),
          placeholder: 'e.g. warmer light, fewer props'
        }),
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.5, color: 'var(--cb-ink-soft)' }, children: 'The reason is used as mood text for the next set. It is not shown to the image model as a scene description.' })
      ]
    }, 'reason'))
  }

  // One primary action per state. The footer says what it needs next.
  const primary = buildWorldPrimary({ state, busy, generating, providerUnavailable, hasStyles: concepts.length > 0, approved: cbWorldApproved(world), mode })
  body.push(jsxs('div', {
    'data-cb-world-actions': state,
    style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '0.5rem', paddingTop: '0.2rem', minWidth: 0 },
    children: [
      primary
        ? jsx('div', {
            'data-cb-world-primary': primary.id,
            style: { display: 'inline-flex' },
            children: jsx(CbAction, {
              variant: 'primary',
              disabled: Boolean(busy) || primary.disabled,
              pending: Boolean(busy) && primary.id === busy,
              onClick: () => {
                if (primary.id === 'concepts') generate('concepts', { brief_patch: patch() })
                else if (primary.id === 'retry-concepts') generate('concepts', { brief_patch: patch() })
                else if (primary.id === 'kit') generate('kit', { style_id: world.selected_concept_id })
                else if (primary.id === 'retry-kit') generate('kit', { style_id: world.selected_concept_id })
                else if (primary.id === 'approve') approveFinal()
                else if (primary.id === 'change') { onReload(); if (onChanged) onChanged() }
              },
              children: primary.label
            })
          }, 'primary')
        : null,
      (state === 'concepts_ready')
        ? jsx('div', {
            'data-cb-world-another': '',
            style: { display: 'inline-flex' },
            children: jsx(CbAction, { variant: 'secondary', disabled: Boolean(busy), onClick: () => generate('concepts', { brief_patch: patch() }), children: 'Try another set' })
          }, 'another')
        : null,
      jsx(CbAction, { variant: 'tertiary', 'data-cb-world-textbook': '', onClick: onClose, children: 'Use Textbook mode' }),
      jsx(CbAction, { variant: 'tertiary', 'data-cb-world-cancel': '', onClick: onClose, children: 'Cancel' })
    ]
  }, 'actions'))

  if (generating) {
    body.push(jsxs('div', {
      'data-cb-world-progress': (job && job.state) || state,
      role: 'status',
      'aria-live': 'polite',
      style: { display: 'flex', alignItems: 'center', gap: '0.5rem', minWidth: 0 },
      children: [
        jsx(sdk.Loader, { label: 'Working on the world' }),
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' }, children: `${stageMessage} — you can leave this open or cancel. No lesson is built until the world is approved.` })
      ]
    }, 'progress'))
  }

  return jsx(WorldStudioFrame, { onClose, state, children: body })
}

function worldField(label, id, value, onChange, placeholder) {
  return jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: '0.2rem', minWidth: 0 },
    children: [
      jsx('label', { htmlFor: id, style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 600, color: 'var(--cb-ink)' }, children: label }),
      jsx(sdk.Input, { id, value, onChange: (event) => onChange(event.target.value), placeholder })
    ]
  }, id)
}

function buildWorldPrimary({ state, busy, generating, providerUnavailable, hasStyles, approved }) {
  if (generating) return { id: 'wait', label: 'Working…', disabled: true }
  if (providerUnavailable) return { id: 'retry-concepts', label: 'Try again' }
  if (state === 'not_requested') return { id: 'concepts', label: 'Show me three directions' }
  if (state === 'concepts_ready') return null
  if (state === 'style_selected') return { id: 'kit', label: 'Build this world' }
  if (state === 'kit_ready') return { id: 'approve', label: 'Use this world' }
  if (state === 'approved') return { id: 'change', label: 'Change world' }
  if (state === 'failed') return hasStyles ? { id: 'retry-kit', label: 'Retry the missing plates' } : { id: 'retry-concepts', label: 'Try the directions again' }
  if (state === 'unavailable') return { id: 'retry-concepts', label: 'Try again' }
  return { id: 'concepts', label: 'Show me three directions' }
}

function WorldStudioFrame({ state, onClose, children }) {
  return jsx('div', {
    'data-cb-world-studio-backdrop': '',
    style: {
      position: 'fixed',
      inset: 0,
      zIndex: 60,
      display: 'flex',
      justifyContent: 'flex-end',
      background: 'color-mix(in srgb, var(--cb-ink) 26%, transparent)'
    },
    onMouseDown: (event) => {
      if (event && event.target === event.currentTarget) onClose()
    },
    children: jsxs('div', {
      role: 'dialog',
      'aria-modal': 'true',
      'aria-labelledby': 'cb-world-studio-title',
      'data-cb-world-studio': state,
      style: {
        width: '46rem',
        maxWidth: '100%',
        height: '100%',
        overflowY: 'auto',
        background: 'var(--cb-paper)',
        color: 'var(--cb-ink)',
        borderLeft: '1px solid var(--cb-rule)',
        display: 'flex',
        flexDirection: 'column',
        gap: '0.75rem',
        padding: '0.85rem 1rem 1.25rem'
      },
      children: [
        jsx('div', {
          style: { display: 'flex', justifyContent: 'flex-end' },
          children: jsx(sdk.Button, {
            size: 'sm',
            variant: 'ghost',
            'data-cb-world-studio-close': '',
            'aria-label': 'Close the World Studio',
            style: { minHeight: '44px' },
            onClick: onClose,
            children: 'Close'
          })
        }),
        ...(Array.isArray(children) ? children : [children])
      ]
    })
  })
}

/**
 * The Textbook → Game prompt. One decision, three plain answers, and the provider-unavailable
 * case says exactly what is preserved instead of offering a world it cannot make.
 */
function ModeSwitchDialog({ mode, world, pending, providerUnavailable, onGenerate, onOpenStudio, onSwitch, onKeep, onCancel }) {
  const state = (world && world.state) || 'not_requested'
  const approved = cbWorldApproved(world)
  const unapproved = state !== 'not_requested' && !approved
  let title = ''
  let body = ''
  let primaryLabel = ''
  let primaryId = ''
  if (providerUnavailable) {
    title = 'Game mode is not available right now'
    body = 'Game mode is not available right now because the image provider is not configured. The course stays in Textbook mode and your lessons are unchanged.'
    primaryLabel = 'Keep Textbook'
    primaryId = 'keep'
  } else if (approved) {
    title = 'This course already has a world.'
    body = 'Switch to Game mode? The approved world is reused; no art is generated.'
    primaryLabel = 'Switch to Game mode'
    primaryId = 'switch'
  } else if (unapproved) {
    title = 'A world is not approved yet.'
    body = 'This course has a world in progress. It stays in Textbook mode until you approve the final kit.'
    primaryLabel = 'Open World Studio'
    primaryId = 'studio'
  } else {
    // Card copy is literal: `Game mode is not available yet. Generate a game world?` with
    // Studio/Cancel. Studio opens the World Studio and starts the three directions there.
    title = 'Game mode is not available yet. Generate a game world?'
    body = 'This course was built in Textbook mode. The World Studio shows three art directions, then builds the kit, then asks for your final approval. Your plan, lessons, checks and evidence stay exactly as they are.'
    primaryLabel = 'Studio'
    primaryId = 'generate'
  }
  return jsx('div', {
    'data-cb-mode-dialog': primaryId,
    style: {
      position: 'fixed',
      inset: 0,
      zIndex: 70,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '1rem',
      background: 'color-mix(in srgb, var(--cb-ink) 34%, transparent)'
    },
    onMouseDown: (event) => {
      if (event && event.target === event.currentTarget) onCancel()
    },
    children: jsxs('div', {
      role: 'dialog',
      'aria-modal': 'true',
      'aria-labelledby': 'cb-mode-dialog-title',
      style: {
        width: '30rem',
        maxWidth: '100%',
        display: 'flex',
        flexDirection: 'column',
        gap: '0.6rem',
        padding: '1rem 1.1rem 1.1rem',
        background: 'var(--cb-paper-raised)',
        border: '1px solid var(--cb-rule)',
        borderTop: '3px solid var(--cb-lamp)',
        borderRadius: '2px'
      },
      children: [
        jsx('h2', {
          id: 'cb-mode-dialog-title',
          style: { margin: 0, fontFamily: CB_SERIF, fontSize: CB_TYPE.heading, fontWeight: 600, lineHeight: 1.15, color: 'var(--cb-ink)' },
          children: title
        }),
        jsx('p', {
          'data-cb-mode-dialog-body': '',
          style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.55, color: 'var(--cb-ink)', maxWidth: '54ch' },
          children: body
        }),
        jsxs('div', {
          style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '0.45rem', paddingTop: '0.2rem' },
          children: [
            jsx('div', {
              'data-cb-mode-primary': primaryId,
              style: { display: 'inline-flex' },
              children: jsx(CbAction, {
                variant: 'primary',
                pending: Boolean(pending),
                onClick: () => {
                  if (primaryId === 'switch') onSwitch()
                  else if (primaryId === 'studio') onOpenStudio()
                  else if (primaryId === 'keep') onKeep()
                  else onGenerate()
                },
                children: primaryLabel
              })
            }),
            primaryId === 'keep' || primaryId === 'generate'
              ? null
              : jsx(CbAction, { variant: 'secondary', 'data-cb-mode-keep': '', onClick: onKeep, children: 'Keep Textbook' }),
            jsx(CbAction, { variant: 'tertiary', 'data-cb-mode-cancel': '', onClick: onCancel, children: 'Cancel' })
          ]
        })
      ]
    })
  })
}

function CoursebookPage() {
  const { state: health, reload: reloadHealth } = useHealth()
  const implemented = useRuntime(health.status)
  // H-147: appearance and motion are the learner's own settings, so they are read here and every
  // surface below (route and pane) paints from the same document. `system` defers to the host.
  const [homePrefs, updateHomePrefs, resetHomePrefs] = useCbHomePrefs()
  // The scoped Ink & Field Notes layer: every Coursebook surface paints from `--cb-*`, and the
  // layer stops at this root, so Hermes chrome keeps its own theme untouched.
  const hostMode = useCbMode()
  const cbMode = cbAppliedMode(hostMode, homePrefs.appearance)
  const systemReduced = useCbReducedMedia()
  const cbMotion = homePrefs.reducedMotion === 'reduce' || systemReduced ? cbMotionFor('reduced') : cbMotionFor('full')
  // H-179: the setting is published to the surfaces below, so `Reduce motion` actually reaches
  // every CbAction whether the learner picked it or the OS asked for it.
  useEffect(() => {
    publishCbMotion(cbMotion)
  }, [cbMotion.reduced])
  const online = useOnline()
  const [settingsOpen, setSettingsOpen] = useState(false)
  const settingsTriggerRef = useRef(null)
  // The classroom the Home rail has selected, named so the classroom section of the sheet can say
  // which classroom its override belongs to rather than "this one".
  const [homeClassroom, setHomeClassroom] = useState(null)
  const [destination, setDestination] = useState(rememberedDestination)
  const [creating, setCreating] = useState(false)
  const [importing, setImporting] = useState(false)
  const [syllabusFlow, setSyllabusFlow] = useState(false)
  const [syllabusSupersedes, setSyllabusSupersedes] = useState(null)
  const [companionTarget, setCompanionTarget] = useState(null)
  const [courseReloadTick, setCourseReloadTick] = useState(0)
  // Set by the mounted course surface when the welcome (first run) is what is on screen. The header
  // then drops its duplicate "New course" button: one screen, one primary action (UX-01).
  const [coursesEmpty, setCoursesEmpty] = useState(false)
  const [openCourse, setOpenCourse] = useState(null)
  // H-146: the selected classroom is shell state, not a backend field and not localStorage. It
  // survives Course Detail because it lives here, beside `openCourse`, and it is never written to
  // progress. A slot switch changes this value only.
  const [selectedCourseId, setSelectedCourseId] = useState(null)
  // GM-002: global Home is the library. Opening a card asks for that course's own home; this id is
  // the only thing that turns Home into a course home, so a fresh mount never silently does it.
  // Leaving Home (or pressing Home again) clears it.
  const [homeCourseId, setHomeCourseId] = useState(null)
  // H-103: "Change the goal" carries the rejected plan's own choices into the create form instead
  // of asking the learner to retype them. It is a seed, not an automatic submit.
  const [createSeed, setCreateSeed] = useState(null)
  // Every door into the create form clears the previous seed; only the plan-rejection action seeds.
  const beginCreate = useCallback((seed = null) => {
    setCreateSeed(seed)
    setCreating(true)
  }, [])
  const [studioCourse, setStudioCourse] = useState(null)
  const [studioSeed, setStudioSeed] = useState(null)
  const [studioRevision, setStudioRevision] = useState(0)
  const [studioReload, setStudioReload] = useState(0)
  // GM-006: the Parent Studio has two entrances. The tab is route state beside the open plan, so
  // leaving and returning keeps the parent where they were, and opening a plan is still a plan.
  const [studioTab, setStudioTab] = useState('plans')

  const changeDestination = useCallback((next) => {
    rememberedDestination = next
    setCreating(false)
    setImporting(false)
    setSyllabusFlow(false)
    setOpenCourse(null)
    setStudioCourse(null)
    setStudioSeed(null)
    // A destination is not a course: leaving Home (or any move) drops the opened course home.
    setHomeCourseId(null)
    setDestination(next)
  }, [])

  // GM-002: selecting a shelf card is the one act that opens a course home. It is a local
  // selection beside the route, never a URL guess, and it does not open Course Detail.
  const openCourseHome = useCallback((row) => {
    if (!row) return
    if (row.recipe !== 'parent' && row.course_id) {
      setSelectedCourseId(row.course_id)
      setHomeCourseId(row.course_id)
    }
  }, [])

  const closeCourseHome = useCallback(() => {
    setHomeCourseId(null)
  }, [])

  // H-147: the sheet closes back onto the control that opened it — Escape, Close and a backdrop
  // click all land here, so keyboard focus never drops to <body>.
  const openSettings = useCallback(() => setSettingsOpen(true), [])
  const closeSettings = useCallback(() => {
    setSettingsOpen(false)
    const wrap = settingsTriggerRef.current
    const button = wrap && typeof wrap.querySelector === 'function' ? wrap.querySelector('button') : null
    if (button && typeof button.focus === 'function') button.focus({ preventScroll: true })
  }, [])

  // A created companion course is opened from the library read, never from the create response:
  // the row carries the enrolment revision the plan tab fences on, and the plan itself is still a
  // background job. This waits for the row to appear instead of inventing one.
  useEffect(() => {
    if (!companionTarget) return undefined
    let cancelled = false
    let attempts = 0
    const find = async () => {
      attempts += 1
      const response = await rpc('library.list', { filter: 'all', limit: 100, sort: 'recent' })
      if (cancelled) return
      const rows = response && response.ok && response.result && Array.isArray(response.result.items) ? response.result.items : []
      const row = rows.find((candidate) => candidate.course_id === companionTarget.courseId)
      if (row) {
        rememberedDestination = 'courses'
        setDestination('courses')
        setSelectedCourseId(row.course_id)
        setOpenCourse({ row, objectiveId: null, view: 'plan' })
        setCompanionTarget(null)
        return
      }
      if (attempts >= 20) setCompanionTarget(null)
    }
    find()
    const handle = setInterval(find, 1500)
    return () => {
      cancelled = true
      clearInterval(handle)
    }
  }, [companionTarget])

  const openNewSyllabusRevision = useCallback((target) => {
    setSyllabusSupersedes(target || {})
    setSyllabusFlow(true)
  }, [])

  useRouteIntent(
    useCallback((intent) => {
      if (!intent) return
      if (intent.kind === 'create') {
        rememberedDestination = 'courses'
        setDestination('courses')
        setCreateSeed(null)
        setCreating(true)
        setSyllabusFlow(false)
        setImporting(false)
        setStudioCourse(null)
        setStudioSeed(null)
      } else if (intent.kind === 'import') {
        rememberedDestination = 'workshop'
        setDestination('workshop')
        setCreating(false)
        setSyllabusFlow(false)
        setImporting(true)
        setStudioCourse(null)
        setStudioSeed(null)
      } else if (intent.kind === 'syllabus') {
        rememberedDestination = 'workshop'
        setDestination('workshop')
        setCreating(false)
        setImporting(false)
        setSyllabusFlow(true)
        setStudioCourse(null)
        setStudioSeed(null)
      } else if (intent.kind === 'library') {
        rememberedDestination = 'workshop'
        setDestination('workshop')
        setCreating(false)
        setSyllabusFlow(false)
        setImporting(false)
        setStudioCourse(null)
        setStudioSeed(null)
      } else if (intent.kind === 'studio') {
        rememberedDestination = 'studio'
        setDestination('studio')
        setCreating(false)
        setImporting(false)
        setOpenCourse(null)
        setStudioCourse(null)
        setStudioSeed(null)
        // "Open Parent Studio" means the authored plans, the entrance the route opens on.
        setStudioTab('plans')
      } else if (intent.kind === 'studio-takehome') {
        // GM-006: the take-home entrance is its own palette destination, not a second route.
        // It lands on the same Parent Studio and never opens a plan behind the tab.
        rememberedDestination = 'studio'
        setDestination('studio')
        setCreating(false)
        setImporting(false)
        setSyllabusFlow(false)
        setOpenCourse(null)
        setStudioCourse(null)
        setStudioSeed(null)
        setStudioTab('takehome')
      } else if (intent.kind === 'studio-new') {
        rememberedDestination = 'studio'
        setDestination('studio')
        setCreating(false)
        setImporting(false)
        setStudioCourse(null)
        setStudioTab('plans')
        setStudioSeed({ initial: null, note: null })
      } else if (intent.kind === 'lesson-block' && intent.row) {
        // GM-012: a citation is a real link back to the block it names. The course detail opens
        // the same section and focuses the exact block; a source-only citation opens the section
        // where the source list lives. The learner pressed the citation, so this is not a
        // background navigation.
        if (intent.row.course_id) setSelectedCourseId(intent.row.course_id)
        setCreating(false)
        setImporting(false)
        setSyllabusFlow(false)
        setStudioCourse(null)
        setOpenCourse({
          row: intent.row,
          objectiveId: intent.objectiveId || null,
          blockId: intent.blockId || null,
          view: null
        })
      }
    }, [])
  )

  const canCreate = Boolean(implemented && implemented.has('course.create'))
  const canImport = Boolean(IMPORT_FLOW_WIRED && implemented && implemented.has('pack.import'))
  const canSyllabus = Boolean(implemented && implemented.has('syllabus.intake.create'))
  const canAuthor = Boolean(implemented && implemented.has('parent.brief.create'))
  // `4vw` measures the window, not the route: with a chat and the explorer open the route is
  // ~400px wide but the window is ~1050, so the old padding took 84px of a 407px column. The
  // route's own measured width picks a gutter that leaves the reading/work column room.
  const measuredRoute = useCbViewportWidth()
  const routePad = measuredRoute > 0 && measuredRoute < 760 ? '0.7rem' : 'clamp(1.25rem, 4vw, 4rem)'

  let body
  if (health.status === 'loading' && !health.result) {
    body = jsx('div', { className: 'py-10', children: jsx(sdk.Loader, { label: 'Reading the Coursebook backend' }) })
  } else if (health.status === 'unavailable') {
    body = jsx(BackendUnavailable, { error: health.error, reload: reloadHealth })
  } else if (health.status === 'degraded') {
    body = jsx(DegradedBody, { reload: reloadHealth, result: health.result })
  } else if (creating) {
    body = jsx(CreateCourseFlow, {
      seed: createSeed,
      onCancel: () => {
        setCreating(false)
        setCreateSeed(null)
      },
      onCreated: () => {
        setCreateSeed(null)
        reloadHealth()
      }
    })
  } else if (importing) {
    body = jsx(PackImportFlow, {
      implemented,
      onCancel: () => setImporting(false),
      onImported: () => {
        setImporting(false)
        reloadHealth()
      }
    })
  } else if (syllabusFlow) {
    body = jsx(SyllabusIntakeFlow, {
      revisionOnly: Boolean(syllabusSupersedes),
      supersedes: syllabusSupersedes,
      onCancel: () => {
        setSyllabusFlow(false)
        setSyllabusSupersedes(null)
      },
      // The course and its plan job are real ids the backend returned; the desk reloads so the
      // new companion course appears from `library.list`, not from this screen's memory.
      onCreated: (created) => {
        const revising = Boolean(syllabusSupersedes)
        setSyllabusFlow(false)
        setSyllabusSupersedes(null)
        if (revising) setCourseReloadTick((value) => value + 1)
        else if (created && created.courseId) setCompanionTarget({ courseId: created.courseId })
        reloadHealth()
      }
    })
  } else if (destination === 'studio') {
    if (studioSeed) {
      body = jsx(StudioBriefForm, {
        initial: studioSeed.initial,
        note: studioSeed.note,
        supported: canAuthor,
        onCancel: () => setStudioSeed(null),
        onCreated: (created) => {
          setStudioSeed(null)
          setStudioCourse({
            course_id: created.course_id,
            enrollment_id: created.enrollment_id,
            title: created.title,
            revision: Number(created.revision || 0)
          })
          setStudioRevision(Number(created.revision || 0))
          setStudioReload((value) => value + 1)
        }
      })
    } else if (studioCourse) {
      body = jsx(StudioDetail, {
        course: studioCourse,
        implemented,
        revision: studioRevision,
        onRevision: setStudioRevision,
        onBack: () => setStudioCourse(null),
        onChanged: () => setStudioReload((value) => value + 1),
        onDuplicate: (brief, note) => setStudioSeed({ initial: brief, note })
      })
    } else {
      body = jsxs('div', {
        'data-cb-parent-studio': studioTab,
        style: { display: 'flex', flexDirection: 'column', minWidth: 0 },
        children: [
          jsx(StudioEntranceTabs, { value: studioTab, onChange: setStudioTab }),
          studioTab === 'takehome'
            ? jsx(TakeHomeStudio, {
                implemented,
                sessionMinutes: homePrefs.sessionMinutes,
                onOpenSettings: openSettings,
                triggerRef: settingsTriggerRef
              })
            : studioTab === 'homework'
              ? jsx(HomeworkStudio, { implemented })
              : jsx(StudioList, {
                implemented,
                reloadSignal: studioReload,
                sessionMinutes: homePrefs.sessionMinutes,
                onOpenSettings: openSettings,
                triggerRef: settingsTriggerRef,
                onCreate: () => setStudioSeed({ initial: null, note: null }),
                onOpen: (row) => {
                  setStudioCourse(row)
                  setStudioRevision(Number(row.revision || 0))
                }
              })
        ]
      })
    }
  } else if (destination === 'workshop') {
    body = jsx(WorkshopView, {
      createOpen: creating,
      implemented,
      canSyllabus,
      canImport,
      onStartSyllabus: canSyllabus ? () => setSyllabusFlow(true) : null,
      onStartImport: canImport ? onImportPlaceholder : null,
      onOpenCourse: (row) => {
        if (row && row.recipe !== 'parent') setSelectedCourseId(row.course_id)
        rememberedDestination = 'workshop'
        setDestination('workshop')
        setOpenCourse({ row, objectiveId: null })
      }
    })
  } else if (openCourse) {
    body = jsx(CourseDetail, {
      row: openCourse.row,
      // GM-010: the play layer obeys the learner's own Game feedback switch on this device.
      prefs: homePrefs,
      focusObjectiveId: openCourse.objectiveId,
      focusBlockId: openCourse.blockId || null,
      focusView: openCourse.view || null,
      // H-147: the view the lesson opens in is the classroom's own override, else the Home default.
      defaultLessonView:
        CB_PRESENTATION_VIEW[cbEffectiveMode(homePrefs, openCourse.row ? openCourse.row.course_id : null)] ||
        'textbook',
      implemented,
      profile: currentScope().profile,
      onBack: () => setOpenCourse(null),
      onChanged: () => reloadHealth(),
      onOpenLibrary: () => {
        setOpenCourse(null)
        rememberedDestination = 'workshop'
        setDestination('workshop')
      },
      reloadSignal: courseReloadTick,
      onChangeGoal: (seed) => {
        setOpenCourse(null)
        rememberedDestination = 'courses'
        setDestination('courses')
        beginCreate(seed || null)
      },
      onNewSyllabus: openNewSyllabusRevision
    })
  } else if (destination === 'courses') {
    body = jsx(CoursesView, {
      createOpen: creating,
      implemented,
      onEmptyChange: setCoursesEmpty,
      onStartCreate: () => beginCreate(),
      onStartSyllabus: canSyllabus ? () => setSyllabusFlow(true) : null,
      onBrowseLibrary: () => changeDestination('workshop'),
      onOpen: (row) => {
        if (row && row.recipe !== 'parent') setSelectedCourseId(row.course_id)
        setOpenCourse({ row, objectiveId: null })
      },
      onShowDesk: () => changeDestination('home')
    })
  } else if (destination === 'home' && homeCourseId) {
    // GM-002: the selected course's home. It keeps the trailhead, the current objective, Continue
    // and the path, and it is reachable only by opening that course on the library Home. It is a
    // distinct surface (`data-cb-course-home`), not the global Home wearing a course.
    body = jsx('div', {
      'data-cb-course-home': homeCourseId,
      style: { display: 'flex', flexDirection: 'column', minWidth: 0 },
      children: jsx(FieldDesk, {
      implemented,
      profile: currentScope().profile,
      online,
      prefs: homePrefs,
      selectedCourseId: homeCourseId,
      onSelectCourse: (courseId) => {
        setSelectedCourseId(courseId)
        setHomeCourseId(courseId)
      },
      onSelectedClassroom: setHomeClassroom,
      onOpenStudio: () => changeDestination('studio'),
      onEmptyChange: setCoursesEmpty,
      onOpen: (row, objectiveId, blockId, view) => {
        if (row && row.recipe !== 'parent') setSelectedCourseId(row.course_id)
        setOpenCourse({ row, objectiveId: objectiveId || null, blockId: blockId || null, view: view || null })
      },
      onShowAll: () => changeDestination('courses'),
      // A course home is not a create surface: the one create action lives on global Home.
      onStartCreate: null,
      onStartSyllabus: null,
        onBrowseLibrary: () => changeDestination('workshop')
      })
    })
  } else {
    // GM-002: global Home is the field library. It launches courses; it is not the selected
    // course's page and never carries Continue, the trailhead or a Japanese lesson scene.
    body = jsx(HomeLibraryPanel, {
      online,
      canCreate,
      onStartCreate: () => beginCreate(),
      onBrowseLibrary: () => changeDestination('workshop'),
      onOpenCourse: openCourseHome,
      onShowAll: () => changeDestination('courses'),
      onOpenStudio: () => changeDestination('studio')
    })
  }

  const statusCopy = backendCopy(health.status)
  const showDestinationNav = health.status === 'ready' && !creating && !importing && !syllabusFlow
  // One stable page title per surface. It is the route's only `h1` in every health and flow
  // state, so the first heading is the page title and never a card's objective; every surface
  // below it is an `h2` region. An open course is its own page ("Course"), not a second "Home"
  // or a second course title (CourseDetail already prints the course name at h2). GM-002: the
  // opened course home under Home is "Course" too — it is not the library.
  const pageTitle = openCourse || (destination === 'home' && homeCourseId)
    ? 'Course'
    : ((DESTINATIONS.find((item) => item.id === destination) || {}).label) || ROUTE_TITLE

  return jsx(CbV3Scope, {
    mode: cbMode,
    className: 'relative flex h-full min-h-0 flex-col',
    attributes: {
      'data-cb-destination': destination,
      'data-cb-route': ROUTE_PATH,
      'data-cb-scope': cbMode,
      'data-cb-motion': cbMotion.preference
    },
    style: { ...cbScopeStyle(cbMode), ...cbHostVars(homePrefs.appearance), paddingLeft: routePad, paddingRight: routePad },
    children: [
      jsx(SkipToContent, {}),
      jsxs('header', {
        className: 'flex shrink-0 flex-col gap-2 pt-3',
        children: [
          jsxs('div', {
            className: 'flex flex-wrap items-start justify-between gap-3',
            children: [
              jsxs('div', {
                className: 'flex min-w-0 flex-col gap-1',
                children: [
                  jsx(CoursebookWordmark, {}),
                  jsx('h1', {
                    'data-cb-page-title': '',
                    style: {
                      margin: 0,
                      fontFamily: CB_SERIF,
                      fontSize: CB_TYPE.display,
                      fontWeight: 600,
                      lineHeight: 1.05,
                      letterSpacing: '-0.02em',
                      color: 'var(--cb-ink)',
                      // H-160: the page title is a single word at the display step. At 460 px with
                      // 200% text the route column is 154 px and "Course" at 72 px is ~220 px, so
                      // the unbreakable token pushed the route to routeOverflowX: 53. `anywhere`
                      // (not `break-word`) also lowers the min-content width, which is what the
                      // wrapping header row sizes itself from.
                      minWidth: 0,
                      maxWidth: '100%',
                      overflowWrap: 'anywhere'
                    },
                    children: pageTitle
                  }),
                  destination === 'home' && !openCourse
                    ? jsx(HomeDefaultsLine, {
                        prefs: homePrefs,
                        classroom: homeClassroom,
                        onOpenSettings: openSettings,
                        triggerRef: settingsTriggerRef
                      })
                    : null
                ]
              }),
              jsxs('div', {
                // The actions must give way before the route does: at a 460 px window the route pane
                // is ~214 px, and two nowrap buttons refused to shrink (V2-2: 19 px at 900, 45 px at
                // 460). Shrinkable + wrapping lets them stack onto their own rows instead of clipping.
                className: 'flex min-w-0 flex-wrap items-center justify-end gap-2',
                children: [
                  online ? null : jsx(sdk.Badge, { variant: 'warn', children: 'Offline' }),
                  statusCopy ? jsx(sdk.Badge, { variant: health.status === 'unavailable' ? 'warn' : 'muted', children: statusCopy }) : null,
                  // GM-002: the course home is one step in from the library Home. This is the way
                  // back; it never relies on the nav's current-item click being re-armed.
                  destination === 'home' && homeCourseId && !openCourse
                    ? jsx(CbAction, {
                        variant: 'tertiary',
                        'data-cb-home-back': '',
                        onClick: closeCourseHome,
                        children: 'Back to Home'
                      }, 'home-back')
                    : null,
                  // H-176 — Settings is a small labelled control in the top-right of the
                  // trailhead, outside the action row. It is not a second primary.
                  destination === 'home' && !openCourse
                    ? jsx('span', {
                        ref: settingsTriggerRef,
                        style: { display: 'inline-flex', alignItems: 'center' },
                        children: jsx(sdk.Button, {
                          size: 'sm',
                          variant: 'ghost',
                          'data-cb-settings-open': '',
                          'aria-label': 'Open Coursebook settings',
                          'aria-haspopup': 'dialog',
                          style: { minHeight: '44px' },
                          onClick: openSettings,
                          children: 'Settings'
                        })
                      }, 'settings')
                    : null,
                  // H-160: UX_SPEC §4 names Courses' page-header primary as **New course**; H-151
                  // measured zero primaries here because this call site was still `secondary`.
                  // Only one eligibility check owns it (non-empty catalog, so FirstRun's own
                  // primary cannot co-exist), so the catalog never carries two.
                  health.status === 'ready' && online && !creating && !importing && destination === 'courses' && canCreate && !coursesEmpty && !openCourse
                    ? jsx(CbAction, { onClick: () => beginCreate(), variant: 'primary', children: 'New course' })
                    : null,
                  // H-196: the Workshop's Library tab owns Import pack and the syllabus door, so
                  // Discover keeps one primary per object (Add to library / Continue) and the route
                  // header carries none of them. The banner stays hidden on this surface.
                  // H-91 P2-4: the Parent Studio landing plate already carries the one
                  // "New lesson plan" primary, so the route header must not repeat it (the gate
                  // counted two primaries with the same label on that surface).
                ]
              })
            ]
          }),
          online
            ? null
            : jsx('div', {
                className: 'text-xs text-(--ui-text-secondary)',
                children:
                  'Offline. Lessons, notes and review keep working from what this profile already saved. ' +
                  'Creating a course, writing a brief and grading open answers are paused until the connection returns.'
              }),
          showDestinationNav
            ? jsx(CbDestinationNav, { value: destination, onChange: changeDestination, onHome: closeCourseHome })
            : null
        ]
      }),
      jsx(PageBody, { label: `${pageTitle} content`, children: body }),
      // H-147: the sheet lives over the route, not at a route of its own. It is only mounted while
      // open, so Home is the only place a reader meets it.
      jsx(HomeSettingsSheet, {
        open: settingsOpen,
        prefs: homePrefs,
        classroom: homeClassroom,
        onUpdate: updateHomePrefs,
        onReset: resetHomePrefs,
        onClose: closeSettings
      })
    ]
  })
}

/**
 * The three destinations, named, with a selected state a colour-blind learner can still read:
 * weight and a lamp underline, plus `aria-current="page"`. It replaces a segmented control whose
 * active state was a fill only.
 */
function CbDestinationNav({ value, onChange, onHome }) {
  return jsx('nav', {
    'data-cb-destination-nav': '',
    'aria-label': 'Coursebook sections',
    className: 'flex flex-wrap items-center gap-x-4',
    children: DESTINATIONS.map((item) => {
      const current = item.id === value
      return jsx(
        'button',
        {
          type: 'button',
          'data-cb-nav-item': item.id,
          'aria-current': current ? 'page' : undefined,
          onClick: () => {
            // GM-002: on the course home the Home destination is still current (it is a step
            // inside Home). Pressing it returns to the library instead of doing nothing.
            if (current) {
              if (item.id === 'home' && onHome) onHome()
              return
            }
            onChange(item.id)
          },
          style: {
            background: 'none',
            border: 'none',
            borderRadius: 0,
            padding: '0.35rem 0',
            cursor: current ? 'default' : 'pointer',
            fontFamily: CB_SANS,
            fontSize: CB_TYPE.meta,
            fontWeight: current ? 600 : 400,
            color: current ? 'var(--cb-ink)' : 'var(--cb-ink-soft)',
            borderBottom: current ? '2px solid var(--cb-lamp)' : '2px solid transparent',
            minHeight: '32px'
          },
          children: item.label
        },
        item.id
      )
    })
  })
}

/**
 * Lesson-context pane. Registered globally, but scoped: it reads the focused chat's stored id
 * and asks the backend for that exact binding. It never shows a lesson from another chat and
 * never guesses one from recency.
 */
/* ── GM-012 · the lesson-bound tutor rail ─────────────────────────────────────
 *
 * The right pane is a tutor, not a chat and not the authoring agent
 * (`docs/GAME-MODE-AND-TUTOR-RAIL-PLAN.md` §7). It is bound to the focused lesson chat's
 * `enrollment_id` / `objective_id` / `lesson_run_id`, it answers through `tutor.ask` with a
 * bounded lesson context, and it owns no tools. Three rules are load-bearing and visible here:
 *
 *   - one thread per lesson run: the thread is read from `tutor.history` for that run, never
 *     from "the newest chat";
 *   - a selection is deliberate: the reading column arms a quote into this rail, the learner
 *     still presses Ask, and nothing is sent by selecting, clicking or dragging;
 *   - practice is a mode of the rail, and only the learner's turns are graded
 *     (`coursebook/conversation.py` reads learner rows only; the rail labels which turns those
 *     are instead of implying the tutor's prose is marked).
 *
 * A failure is a named state, never an empty thread or a fabricated answer.
 */

const TUTOR_MODES = Object.freeze([
  { id: 'ask', label: 'Ask' },
  { id: 'practice', label: 'Practice' }
])
const TUTOR_ASK_PLACEHOLDER = 'Ask about this lesson…'
const TUTOR_MAX_QUOTE = 600
const TUTOR_SHEET_BREAKPOINT = 520
const TUTOR_HINT_QUESTION = 'Give me a hint for this check. Do not give the answer.'

/**
 * The selected excerpt is module state, not a callback chain.
 *
 * The route's reading column and the contributed pane are two React roots of the same module
 * instance, so a small broadcast store is the honest seam: the pill arms an excerpt, the pane
 * subscribes, and nothing about the lesson route is re-rendered by a chat.
 */
const tutorQuoteListeners = new Set()
let pendingTutorQuote = null
const tutorFocusListeners = new Set()
let tutorFocusTick = 0

function cbTutorQuoteText(value) {
  const text = String(value == null ? '' : value).replace(/\s+/g, ' ').trim()
  return text.length > TUTOR_MAX_QUOTE ? text.slice(0, TUTOR_MAX_QUOTE) : text
}

function armTutorQuote(quote) {
  const text = cbTutorQuoteText(quote && quote.text)
  if (!text) return null
  pendingTutorQuote = {
    text,
    blockId: (quote && quote.blockId) || null,
    courseId: (quote && quote.courseId) || null,
    objectiveId: (quote && quote.objectiveId) || null,
    source: (quote && quote.source) || 'selection',
    armedAt: Date.now()
  }
  tutorQuoteListeners.forEach((listener) => listener(pendingTutorQuote))
  revealCoursebookPane()
  return pendingTutorQuote
}

function clearTutorQuote() {
  pendingTutorQuote = null
  tutorQuoteListeners.forEach((listener) => listener(null))
}

function useTutorQuote() {
  const [quote, setQuote] = useState(pendingTutorQuote)
  useEffect(() => {
    const listener = (next) => setQuote(next)
    tutorQuoteListeners.add(listener)
    if (pendingTutorQuote) listener(pendingTutorQuote)
    return () => {
      tutorQuoteListeners.delete(listener)
    }
  }, [])
  return quote
}

function requestTutorFocus() {
  tutorFocusTick += 1
  tutorFocusListeners.forEach((listener) => listener(tutorFocusTick))
}

function useTutorFocusTick() {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    const listener = (value) => setTick(value)
    tutorFocusListeners.add(listener)
    return () => {
      tutorFocusListeners.delete(listener)
    }
  }, [])
  return tick
}

/** The one shape `tutor.ask` accepts. No question means no request, whatever is selected. */
function tutorAskPayload({ courseId, enrollmentId, objectiveId, lessonRunId, question, quote, mode }) {
  const text = String(question == null ? '' : question).trim()
  if (!courseId || !enrollmentId || !objectiveId || !lessonRunId) return null
  if (!text) return null
  const selected = cbTutorQuoteText(quote && quote.text)
  return {
    course_id: courseId,
    enrollment_id: enrollmentId,
    objective_id: objectiveId,
    lesson_run_id: lessonRunId,
    question: text,
    block_id: selected && quote && quote.blockId ? quote.blockId : null,
    selected_text: selected || null,
    mode: mode === 'practice' ? 'practice' : 'ask'
  }
}

/** The served document by block id. Nothing outside this index can be cited. */
function cbTutorBlockIndex(page) {
  const blocks = (page && page.document && page.document.blocks) || []
  const index = {}
  for (const block of blocks) {
    if (block && block.id) index[block.id] = block
  }
  return index
}

/** Authored glossary entries only. A term without a gloss is not a glossary card. */
function cbTutorGlossary(page) {
  const document = page && page.document ? page.document : {}
  const raw = Array.isArray(document.glossary)
    ? document.glossary
    : Array.isArray(page && page.glossary)
      ? page.glossary
      : []
  const entries = []
  const seen = new Set()
  for (const item of raw) {
    if (!item || typeof item !== 'object') continue
    const term = String(item.term || '').trim()
    const gloss = String(item.gloss || '').trim()
    if (!term || !gloss) continue
    const key = term.toLowerCase()
    if (seen.has(key)) continue
    seen.add(key)
    entries.push({
      term,
      gloss,
      reading: item.reading ? String(item.reading) : null,
      pronunciation: item.pronunciation ? String(item.pronunciation) : null,
      blockId: item.block_id || null
    })
    if (entries.length >= 24) break
  }
  return entries
}

/** Only citations that resolve to a served block or source. A bad id is omitted, never invented. */
function cbTutorCitations(turn, blockIndex, sourceIndex) {
  const raw = (turn && Array.isArray(turn.citations) && turn.citations) || []
  const resolved = []
  const seen = new Set()
  for (const item of raw) {
    if (!item || typeof item !== 'object') continue
    const id = String(item.id || '').trim()
    if (!id) continue
    let kind = item.kind === 'source' ? 'source' : item.kind === 'block' ? 'block' : null
    if (!kind) kind = (blockIndex && blockIndex[id]) ? 'block' : (sourceIndex && sourceIndex[id]) ? 'source' : null
    if (kind === 'block' && !(blockIndex && blockIndex[id])) continue
    if (kind === 'source' && !(sourceIndex && sourceIndex[id])) continue
    if (!kind) continue
    const key = `${kind}:${id}`
    if (seen.has(key)) continue
    seen.add(key)
    const fallback = kind === 'block'
      ? (blockIndex[id].headline || blockIndex[id].role || id)
      : (sourceIndex[id].title || id)
    resolved.push({ kind, id, label: String(item.label || fallback) })
  }
  return resolved
}

/** History turns, normalized. A malformed row is omitted rather than printed as an answer. */
function cbTutorTurns(payload) {
  const raw = payload && Array.isArray(payload.turns) ? payload.turns : []
  const turns = []
  for (const turn of raw) {
    if (!turn || typeof turn !== 'object') continue
    if (turn.role !== 'learner' && turn.role !== 'tutor') continue
    const text = String(turn.text || '').trim()
    if (!text) continue
    turns.push({
      id: turn.id || null,
      ordinal: Number(turn.ordinal) || turns.length + 1,
      role: turn.role,
      text,
      block_id: turn.block_id || null,
      selected_text: turn.selected_text || null,
      citations: Array.isArray(turn.citations) ? turn.citations : [],
      state: turn.state || null
    })
  }
  return turns
}

/** The count the grader uses: learner rows only. Tutor prose is never counted, never graded. */
function cbTutorLearnerTurnCount(transcript) {
  return (Array.isArray(transcript) ? transcript : []).filter((turn) => turn && turn.speaker === 'learner').length
}

/** The rail is a side column on a wide surface and a bottom sheet on a phone-width one. */
function tutorRailLayout(width) {
  const value = Number(width)
  if (!Number.isFinite(value) || value <= 0) return 'sheet'
  return value < TUTOR_SHEET_BREAKPOINT ? 'sheet' : 'side'
}

function cbTutorPracticeDeclaration(check) {
  const practice = check && check.stimulus ? check.stimulus.practice : null
  return practice && typeof practice === 'object' ? practice : null
}

/** Hint copy: the policy label the backend declared, never a fabricated hint. */
function cbTutorHintAvailable(check) {
  const stimulus = check && check.stimulus ? check.stimulus : null
  if (!stimulus) return false
  const policy = stimulus.assistance_policy && typeof stimulus.assistance_policy === 'object'
    ? stimulus.assistance_policy
    : {}
  const hint = policy.hint
  if (hint === 'available') return true
  if (hint === 'after_attempt') return Number(check.attempt_count || 0) > 0
  return false
}

/** One tutor or learner turn in the rail's notebook margin. */
function TutorTurn({ turn, blockIndex, sourceIndex, onCitation }) {
  const learner = turn.role === 'learner'
  const citations = cbTutorCitations(turn, blockIndex, sourceIndex)
  const withheld = turn.state === 'answer_withheld'
  return jsxs('article', {
    'data-cb-tutor-turn': turn.role,
    'data-cb-tutor-turn-ordinal': String(turn.ordinal),
    'data-cb-tutor-graded': learner && !withheld ? 'true' : 'false',
    style: {
      display: 'flex',
      flexDirection: 'column',
      gap: '0.25rem',
      paddingLeft: learner ? '0.55rem' : 0,
      borderLeft: learner ? '2px solid var(--cb-rule)' : 'none',
      minWidth: 0
    },
    children: [
      jsx('div', {
        style: {
          fontFamily: CB_SANS,
          fontSize: CB_TYPE.caption,
          fontWeight: 600,
          letterSpacing: '0.01em',
          color: 'var(--cb-ink-soft)'
        },
        children: learner ? 'You' : 'Tutor'
      }),
      learner && turn.selected_text
        ? jsx('div', {
            'data-cb-tutor-turn-quote': turn.block_id || '',
            style: {
              margin: 0,
              paddingLeft: '0.45rem',
              borderLeft: '2px solid var(--cb-accent)',
              fontFamily: CB_SERIF,
              fontSize: CB_TYPE.meta,
              lineHeight: 1.5,
              color: 'var(--cb-ink-soft)'
            },
            children: turn.selected_text
          })
        : null,
      learner
        ? jsx('p', {
            style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.55, color: 'var(--cb-ink)', overflowWrap: 'anywhere' },
            children: turn.text
          })
        : jsx(ProseText, {
            style: { maxWidth: '100%', fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.6, color: 'var(--cb-ink)' },
            text: turn.text
          }),
      withheld
        ? jsx('span', {
            'data-cb-tutor-answer': 'withheld',
            style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' },
            children: 'The answer stays hidden while the check is open.'
          })
        : null,
      citations.length
        ? jsxs('div', {
            'data-cb-tutor-citations': String(citations.length),
            style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '0.3rem 0.6rem', paddingTop: '0.1rem' },
            children: [
              jsx('span', {
                style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' },
                children: citations.length === 1 ? 'Cited from' : 'Cited from'
              }),
              ...citations.map((citation) =>
                jsxs('button', {
                  type: 'button',
                  'data-cb-tutor-citation': citation.kind,
                  'data-cb-tutor-citation-target': citation.id,
                  'aria-label': `Go to ${citation.label}`,
                  onClick: () => onCitation && onCitation(citation),
                  style: {
                    display: 'inline-flex',
                    alignItems: 'center',
                    minHeight: '24px',
                    padding: '0.05rem 0.4rem',
                    border: '1px solid var(--cb-rule)',
                    borderRadius: '2px',
                    background: 'var(--cb-paper)',
                    color: 'var(--cb-ink)',
                    fontFamily: CB_SANS,
                    fontSize: CB_TYPE.caption,
                    fontWeight: 600,
                    lineHeight: 1.35,
                    textAlign: 'left',
                    cursor: 'pointer',
                    overflowWrap: 'anywhere'
                  },
                  children: citation.kind === 'source' ? `Source · ${citation.label}` : citation.label
                }, `${turn.ordinal}-${citation.kind}-${citation.id}`)
              )
            ]
          })
        : null
    ]
  }, turn.id || `${turn.role}-${turn.ordinal}`)
}

/** The authored glossary, as real buttons — no arbitrary prose is a target. */
function TutorGlossary({ entries, onAskTerm, onAddTermQuote }) {
  const [openTerm, setOpenTerm] = useState(null)
  if (!entries || entries.length === 0) return null
  const current = openTerm ? entries.find((entry) => entry.term === openTerm) : null
  return jsxs('section', {
    'data-cb-tutor-glossary': String(entries.length),
    'aria-label': 'Glossary',
    style: { display: 'flex', flexDirection: 'column', gap: '0.3rem' },
    children: [
      jsx('div', {
        style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 600, letterSpacing: '0.01em', color: 'var(--cb-ink-soft)' },
        children: 'Glossary'
      }),
      jsx('div', {
        style: { display: 'flex', flexWrap: 'wrap', gap: '0.25rem 0.55rem' },
        children: entries.map((entry) =>
          jsx('button', {
            type: 'button',
            'data-cb-tutor-term': entry.term,
            'aria-expanded': openTerm === entry.term ? 'true' : 'false',
            'aria-label': `Glossary: ${entry.term}`,
            onClick: () => setOpenTerm(openTerm === entry.term ? null : entry.term),
            style: {
              minHeight: '24px',
              padding: 0,
              border: 'none',
              background: 'transparent',
              color: 'var(--cb-ink)',
              fontFamily: CB_SERIF,
              fontSize: CB_TYPE.meta,
              lineHeight: 1.5,
              textDecoration: 'underline',
              textDecorationStyle: 'dotted',
              textDecorationColor: 'var(--cb-accent)',
              textUnderlineOffset: '3px',
              cursor: 'pointer'
            },
            children: entry.term
          }, `term-${entry.term}`)
        )
      }),
      current
        ? jsxs('div', {
            'data-cb-tutor-term-card': current.term,
            role: 'group',
            'aria-label': `${current.term} glossary entry`,
            style: {
              display: 'flex',
              flexDirection: 'column',
              gap: '0.2rem',
              padding: '0.45rem 0.55rem',
              border: '1px solid var(--cb-rule)',
              borderLeft: '2px solid var(--cb-lamp)',
              background: 'var(--cb-paper-raised)',
              borderRadius: 0
            },
            children: [
              jsxs('div', {
                style: { display: 'flex', flexWrap: 'wrap', alignItems: 'baseline', gap: '0.35rem' },
                children: [
                  jsx('span', { style: { fontFamily: CB_SERIF, fontSize: CB_TYPE.body, fontWeight: 600, color: 'var(--cb-ink)' }, children: current.term }),
                  current.reading
                    ? jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' }, children: current.reading })
                    : null,
                  current.pronunciation
                    ? jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' }, children: current.pronunciation })
                    : null
                ]
              }),
              jsx('p', { style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.55, color: 'var(--cb-ink)' }, children: current.gloss }),
              jsxs('div', {
                style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '0.4rem', paddingTop: '0.15rem' },
                children: [
                  jsx(CbAction, {
                    variant: 'tertiary',
                    'data-cb-tutor-term-ask': current.term,
                    onClick: () => (onAskTerm ? onAskTerm(current) : onAddTermQuote && onAddTermQuote(current)),
                    children: 'Ask more'
                  }),
                  onAddTermQuote
                    ? jsx(CbAction, {
                        variant: 'tertiary',
                        'data-cb-tutor-term-quote': current.term,
                        onClick: () => onAddTermQuote(current),
                        children: 'Use in a question'
                      })
                    : null
                ]
              })
            ]
          })
        : null
    ]
  })
}

/**
 * The rail itself. Presentational by design: the pane owns the reads and the writes, so every
 * state (loading, unavailable, provider failure, changed lesson, practice) can be rendered and
 * tested without a backend.
 */
function TutorRail({
  state = 'ready',
  width = 0,
  courseTitle = '',
  sectionTitle = '',
  objectiveTitle = '',
  contextChip = '',
  turns = [],
  blockIndex = {},
  sourceIndex = {},
  glossary = [],
  checkOpen = false,
  hint = null,
  mode = 'ask',
  quote = null,
  draft = '',
  busy = false,
  notice = null,
  detached = false,
  practice = null,
  practiceAvailable = false,
  practiceSurface = null,
  practiceError = null,
  onModeChange,
  onDraftChange,
  onSend,
  onRemoveQuote,
  onCitation,
  onHint,
  onTermQuote,
  onRetry,
  onStartPractice,
  onEndPractice,
  onOpenSection,
  onOpenCoursebook
}) {
  const layout = tutorRailLayout(width)
  const sheet = layout === 'sheet'
  const declaration = practice && practice.declaration ? practice.declaration : null
  const transcript = practice && Array.isArray(practice.transcript) ? practice.transcript : []
  const practiceState = practice && practice.state ? practice.state : 'none'
  const modeOptions = TUTOR_MODES.filter((option) => option.id === 'ask' || practiceAvailable)
  const busyLabel = mode === 'practice' ? 'Sending…' : 'Thinking…'
  const line = sheet ? CB_TYPE.meta : CB_TYPE.caption
  const muted = { fontFamily: CB_SANS, fontSize: line, lineHeight: 1.5, color: 'var(--cb-ink-soft)' }

  const statusBanner = (label, action) =>
    jsxs('div', {
      role: 'status',
      'data-cb-tutor-notice': label,
      style: { display: 'flex', flexDirection: 'column', gap: '0.35rem', padding: '0.45rem 0.55rem', border: '1px solid var(--cb-rule)', borderLeft: '2px solid var(--cb-coral)', background: 'var(--cb-paper-raised)', borderRadius: 0 },
      children: [
        jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.5, color: 'var(--cb-ink)' }, children: label }),
        action || null
      ]
    })

  let body
  if (state === 'no-lesson') {
    body = jsxs('div', {
      'data-cb-tutor-body': 'no-lesson',
      style: { display: 'flex', flexDirection: 'column', gap: '0.5rem' },
      children: [
        jsx(sdk.EmptyState, {
          title: 'Open a lesson to ask the tutor.',
          description: 'The tutor answers about the section you are reading, with the lesson’s own words and sources.'
        }),
        jsx(CbAction, {
          variant: 'secondary',
          'data-cb-tutor-open-coursebook': '',
          onClick: onOpenCoursebook,
          children: 'Open Coursebook'
        })
      ]
    })
  } else if (state === 'loading') {
    body = jsxs('div', {
      'data-cb-tutor-body': 'loading',
      style: { display: 'flex', flexDirection: 'column', gap: '0.4rem' },
      children: [
        jsx(sdk.Loader, { label: 'Reading this lesson…' }),
        jsx('span', { style: muted, children: 'The composer stays closed until the lesson context is here.' })
      ]
    })
  } else if (state === 'unavailable') {
    body = jsxs('div', {
      'data-cb-tutor-body': 'unavailable',
      style: { display: 'flex', flexDirection: 'column', gap: '0.45rem' },
      children: [
        statusBanner('The tutor is unavailable. The lesson is still readable.', null),
        onRetry
          ? jsx(CbAction, { variant: 'secondary', 'data-cb-tutor-retry': '', onClick: onRetry, children: 'Retry' })
          : null
      ]
    })
  } else if (state === 'provider-failure') {
    body = jsxs('div', {
      'data-cb-tutor-body': 'provider-failure',
      style: { display: 'flex', flexDirection: 'column', gap: '0.45rem' },
      children: [
        statusBanner('The tutor could not answer. Nothing was graded.', null),
        onRetry
          ? jsx(CbAction, { variant: 'secondary', 'data-cb-tutor-retry': '', onClick: onRetry, children: 'Retry' })
          : null
      ]
    })
  } else if (state === 'lesson-changed') {
    body = jsxs('div', {
      'data-cb-tutor-body': 'lesson-changed',
      style: { display: 'flex', flexDirection: 'column', gap: '0.45rem' },
      children: [
        statusBanner('This thread belongs to the previous section.', null),
        jsx('span', { style: muted, children: 'The lesson moved on. This thread is kept with the run it was written in.' }),
        jsxs('div', {
          style: { display: 'flex', flexWrap: 'wrap', gap: '0.4rem' },
          children: [
            onRetry ? jsx(CbAction, { variant: 'secondary', 'data-cb-tutor-read-old': '', onClick: onRetry, children: 'Read these turns' }) : null,
            onOpenSection ? jsx(CbAction, { variant: 'tertiary', onClick: onOpenSection, children: 'Open the section' }) : null
          ]
        })
      ]
    })
  } else {
    const thread = jsx('div', {
      'data-cb-tutor-thread': String(turns.length),
      role: 'log',
      'aria-live': 'polite',
      'aria-label': 'Tutor thread',
      style: { display: 'flex', flexDirection: 'column', gap: '0.7rem', minWidth: 0 },
      children: turns.length
        ? turns.map((turn) => jsx(TutorTurn, { turn, blockIndex, sourceIndex, onCitation }, turn.id || `${turn.role}-${turn.ordinal}`))
        : jsx('p', {
            style: { margin: 0, fontFamily: CB_SERIF, fontSize: CB_TYPE.meta, lineHeight: 1.55, color: 'var(--cb-ink-soft)' },
            children: 'Ask about a word, a step or the check. The answer cites the lesson it came from.'
          })
    })
    const composer = jsxs('div', {
      'data-cb-tutor-composer': mode,
      style: { display: 'flex', flexDirection: 'column', gap: '0.35rem', paddingTop: sheet ? '0.5rem' : '0.35rem', borderTop: '1px solid var(--cb-rule)' },
      children: [
        quote
          ? jsxs('div', {
              'data-cb-tutor-quote': quote.blockId || 'text',
              style: { display: 'flex', alignItems: 'flex-start', gap: '0.4rem', paddingLeft: '0.45rem', borderLeft: '2px solid var(--cb-accent)', minWidth: 0 },
              children: [
                jsx('span', {
                  'data-cb-tutor-quote-text': '',
                  style: { flex: '1 1 auto', minWidth: 0, fontFamily: CB_SERIF, fontSize: CB_TYPE.meta, lineHeight: 1.5, color: 'var(--cb-ink-soft)', overflowWrap: 'anywhere' },
                  children: quote.text
                }),
                jsx('button', {
                  type: 'button',
                  'data-cb-tutor-quote-remove': '',
                  'aria-label': 'Remove the selected excerpt',
                  onClick: onRemoveQuote,
                  style: {
                    display: 'inline-flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '24px',
                    height: '24px',
                    flex: '0 0 auto',
                    padding: 0,
                    border: '1px solid var(--cb-rule)',
                    borderRadius: '2px',
                    background: 'var(--cb-paper)',
                    color: 'var(--cb-ink)',
                    cursor: 'pointer'
                  },
                  children: jsx(sdk.Codicon, { name: 'close', size: CB_ICON_UI })
                })
              ]
            })
          : null,
        jsx('label', {
          htmlFor: 'cb-tutor-input',
          style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 600, color: 'var(--cb-ink-soft)' },
          children: mode === 'practice' ? 'Your turn in the practice' : 'Your question'
        }),
        jsx(sdk.Textarea, {
          id: 'cb-tutor-input',
          'data-cb-tutor-input': '',
          'aria-describedby': 'cb-tutor-input-help',
          value: draft,
          rows: sheet ? 2 : 3,
          placeholder: mode === 'practice' ? 'Answer in the practice scene…' : TUTOR_ASK_PLACEHOLDER,
          onChange: (event) => onDraftChange && onDraftChange(event && event.target ? event.target.value : ''),
          onKeyDown: (event) => {
            if (!event || event.key !== 'Enter' || event.shiftKey) return
            event.preventDefault()
            if (!busy && String(draft || '').trim()) onSend && onSend()
          }
        }),
        jsx('p', {
          id: 'cb-tutor-input-help',
          style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.45, color: 'var(--cb-ink-soft)' },
          children: mode === 'practice'
            ? 'Only your turns are graded. The tutor stays in the scene and never marks you.'
            : 'The tutor answers about this lesson only. Enter sends; Shift+Enter starts a new line.'
        }),
        jsxs('div', {
          style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: '0.4rem' },
          children: [
            hint
              ? hint.used
                ? jsx('span', {
                    'data-cb-tutor-assist': 'hinted',
                    role: 'status',
                    style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 600, color: 'var(--cb-ink-soft)' },
                    children: 'Hint recorded — this answer is marked hinted'
                  })
                : jsx(CbAction, {
                    variant: 'tertiary',
                    'data-cb-tutor-hint': hint.available ? 'available' : 'unavailable',
                    disabled: !hint.available || busy,
                    onClick: onHint,
                    children: 'Ask for a hint'
                  })
              : null,
            jsx(CbAction, {
              variant: 'primary',
              'data-cb-tutor-send': mode,
              disabled: Boolean(busy) || !String(draft || '').trim(),
              pending: Boolean(busy),
              onClick: onSend,
              children: busy ? busyLabel : mode === 'practice' ? 'Say it' : 'Ask'
            }),
            mode === 'practice' && practiceState === 'active'
              ? jsx(CbAction, {
                  variant: 'secondary',
                  'data-cb-tutor-practice-end': '',
                  disabled: Boolean(busy),
                  onClick: onEndPractice,
                  children: 'End practice'
                })
              : null
          ]
        })
      ]
    })

    let modeBody
    if (mode === 'practice') {
      if (!practiceAvailable) {
        modeBody = jsxs('div', {
          'data-cb-tutor-practice': 'unavailable',
          style: { display: 'flex', flexDirection: 'column', gap: '0.4rem' },
          children: [
            jsx('p', { style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.55, color: 'var(--cb-ink)' }, children: 'Practice is not available in this build. You can still ask about the lesson.' }),
            jsx(CbAction, { variant: 'secondary', 'data-cb-tutor-mode-back': '', onClick: () => onModeChange && onModeChange('ask'), children: 'Back to Ask' })
          ]
        })
      } else if (practiceError) {
        modeBody = jsxs('div', {
          'data-cb-tutor-practice': 'error',
          style: { display: 'flex', flexDirection: 'column', gap: '0.4rem' },
          children: [
            statusBanner('Practice could not be read. Nothing was graded.', null),
            onRetry ? jsx(CbAction, { variant: 'secondary', onClick: onRetry, children: 'Retry' }) : null
          ]
        })
      } else if (practiceState === 'none') {
        modeBody = jsxs('div', {
          'data-cb-tutor-practice': 'ready',
          style: { display: 'flex', flexDirection: 'column', gap: '0.4rem' },
          children: [
            declaration && declaration.scenario
              ? jsx('p', { style: { margin: 0, fontFamily: CB_SERIF, fontSize: CB_TYPE.meta, lineHeight: 1.55, color: 'var(--cb-ink)' }, children: declaration.scenario })
              : null,
            declaration && (declaration.tutor_role || declaration.learner_role)
              ? jsx('p', {
                  style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.5, color: 'var(--cb-ink-soft)' },
                  children: `You are the ${declaration.learner_role || 'learner'}; the tutor is the ${declaration.tutor_role || 'other speaker'}.`
                })
              : null,
            jsx(CbAction, { variant: 'primary', 'data-cb-tutor-practice-start': '', disabled: Boolean(busy), onClick: onStartPractice, children: 'Start practice' }),
            jsx('p', { style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.45, color: 'var(--cb-ink-soft)' }, children: 'Only your turns are graded, after you end the practice.' })
          ]
        })
      } else {
        const graded = Boolean(practice && practice.verdict)
        modeBody = jsxs('div', {
          'data-cb-tutor-practice': practiceState,
          'data-cb-tutor-practice-graded': graded ? 'true' : 'false',
          style: { display: 'flex', flexDirection: 'column', gap: '0.5rem' },
          children: [
            jsx('div', {
              'data-cb-tutor-practice-transcript': String(transcript.length),
              role: 'log',
              'aria-label': 'Practice transcript',
              style: { display: 'flex', flexDirection: 'column', gap: '0.5rem' },
              children: transcript.map((turn) =>
                jsxs('article', {
                  'data-cb-tutor-turn': turn.speaker === 'learner' ? 'learner' : 'tutor',
                  'data-cb-tutor-graded': turn.speaker === 'learner' ? 'true' : 'false',
                  style: { display: 'flex', flexDirection: 'column', gap: '0.15rem', paddingLeft: turn.speaker === 'learner' ? '0.55rem' : 0, borderLeft: turn.speaker === 'learner' ? '2px solid var(--cb-rule)' : 'none' },
                  children: [
                    jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, fontWeight: 600, color: 'var(--cb-ink-soft)' }, children: turn.speaker === 'learner' ? 'You · graded' : 'Tutor · not graded' }),
                    jsx('p', { style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.meta, lineHeight: 1.55, color: 'var(--cb-ink)', overflowWrap: 'anywhere' }, children: turn.text })
                  ]
                }, `practice-${turn.ordinal}`)
              )
            }),
            practice && practice.remaining !== undefined
              ? jsx('p', { style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)' }, children: `${plural(Number(practice.remaining) || 0, 'turn', 'turns')} left before you can end.` })
              : null,
            graded
              ? jsxs('div', {
                  'data-cb-tutor-verdict': practice.verdict,
                  style: { display: 'flex', flexDirection: 'column', gap: '0.3rem', padding: '0.45rem 0.55rem', border: '1px solid var(--cb-rule)', borderLeft: '2px solid var(--cb-lamp)', background: 'var(--cb-paper-raised)', borderRadius: 0 },
                  children: [
                    jsx('span', { style: { fontFamily: CB_SANS, fontSize: CB_TYPE.meta, fontWeight: 600, color: 'var(--cb-ink)' }, children: practice.feedback || 'The practice was graded.' }),
                    jsx('span', { style: muted, children: 'Only your turns were read. Review grading has the stored result.' }),
                    jsx(CbAction, { variant: 'tertiary', 'data-cb-tutor-mode-back': '', onClick: () => onModeChange && onModeChange('ask'), children: 'Back to Ask' })
                  ]
                })
              : null
          ]
        })
      }
      body = practiceSurface
        ? jsx('div', {
            'data-cb-tutor-body': 'practice',
            'data-cb-tutor-practice-surface': practiceState,
            style: { display: 'flex', flexDirection: 'column', gap: '0.6rem' },
            children: practiceSurface
          })
        : jsxs('div', {
            'data-cb-tutor-body': 'practice',
            style: { display: 'flex', flexDirection: 'column', gap: '0.6rem' },
            children: [modeBody, practiceState === 'active' ? composer : null]
          })
    } else {
      body = jsxs('div', {
        'data-cb-tutor-body': 'ask',
        style: { display: 'flex', flexDirection: 'column', gap: '0.6rem' },
        children: [
          jsx(TutorGlossary, { entries: glossary, onTermQuote }),
          thread,
          notice ? jsx('div', { role: 'status', 'data-cb-tutor-notice': '', style: muted, children: notice }) : null,
          checkOpen
            ? jsx('p', {
                'data-cb-tutor-check-open': '',
                style: { margin: 0, fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.45, color: 'var(--cb-ink-soft)' },
                children: 'A check is open. The tutor helps you work it out; it does not show the answer or record a verdict.'
              })
            : null,
          composer
        ]
      })
    }
  }

  return jsxs('aside', {
    'data-cb-tutor-rail': layout,
    'data-cb-tutor-state': state,
    'data-cb-tutor-mode': mode,
    'aria-label': 'Lesson tutor',
    style: {
      display: 'flex',
      flexDirection: 'column',
      gap: '0.55rem',
      minWidth: 0,
      width: '100%',
      ...(sheet
        ? { paddingTop: '0.6rem', borderTop: '1px solid var(--cb-rule)' }
        : { maxWidth: '24rem' })
    },
    children: [
      jsxs('header', {
        'data-cb-tutor-header': '',
        style: { display: 'flex', flexDirection: 'column', gap: '0.2rem', paddingBottom: '0.4rem', borderBottom: '1px solid var(--cb-rule)', minWidth: 0 },
        children: [
          jsxs('div', {
            style: { display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: '0.5rem', minWidth: 0 },
            children: [
              jsx('h2', {
                style: { margin: 0, fontFamily: CB_SERIF, fontSize: sheet ? CB_TYPE.lead : CB_TYPE.body, fontWeight: 600, lineHeight: 1.2, color: 'var(--cb-ink)' },
                children: 'Tutor'
              }),
              contextChip
                ? jsx('span', {
                    'data-cb-tutor-context': contextChip,
                    style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, color: 'var(--cb-ink-soft)', textAlign: 'right' },
                    children: contextChip
                  })
                : null
            ]
          }),
          jsx('div', {
            'data-cb-tutor-lesson': '',
            style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.45, color: 'var(--cb-ink-soft)', overflowWrap: 'anywhere' },
            children: [courseTitle, objectiveTitle || sectionTitle].filter(Boolean).join(' · ') || 'This lesson'
          }),
          detached
            ? jsx('div', {
                'data-cb-tutor-detached': '',
                role: 'status',
                style: { fontFamily: CB_SANS, fontSize: CB_TYPE.caption, lineHeight: 1.45, color: 'var(--cb-ink-soft)' },
                children: 'This lesson’s chat is disconnected. You can still ask about the section; the thread stays with its run.'
              })
            : null
        ]
      }),
      modeOptions.length > 1
        ? jsx(LearningTabs, {
            options: modeOptions,
            value: mode,
            onChange: (next) => onModeChange && onModeChange(next),
            phone: sheet,
            ariaLabel: 'Tutor mode'
          })
        : null,
      body
    ]
  })
}

/**
 * The selection pill: it appears only after a completed selection inside the lesson's reading
 * column, and pressing it arms a quote. It never sends, never opens a chat and never fires on a
 * single click or a drag that selected nothing.
 */
function TutorSelectionPill({ context }) {
  const [pill, setPill] = useState(null)
  const contextRef = useRef(context)
  contextRef.current = context
  useEffect(() => {
    if (typeof document === 'undefined' || typeof window === 'undefined') return undefined
    const read = () => {
      const selection = typeof window.getSelection === 'function' ? window.getSelection() : null
      if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
        setPill(null)
        return
      }
      const text = cbTutorQuoteText(selection.toString())
      if (text.length < 2) {
        setPill(null)
        return
      }
      const range = selection.getRangeAt(0)
      let node = range.commonAncestorContainer
      if (node && node.nodeType !== 1) node = node.parentElement
      const block = node && node.closest ? node.closest('[data-cb-block]') : null
      if (!block) {
        setPill(null)
        return
      }
      const rect = range.getBoundingClientRect()
      setPill({
        text,
        blockId: block.getAttribute('data-cb-block') || null,
        x: rect.left + rect.width / 2,
        y: rect.top
      })
    }
    const arm = () => {
      const current = contextRef.current || {}
      if (!pill) return
      armTutorQuote({
        text: pill.text,
        blockId: pill.blockId,
        courseId: current.courseId || null,
        objectiveId: current.objectiveId || null,
        source: 'selection'
      })
      requestTutorFocus()
      setPill(null)
    }
    const onPointerUp = () => window.setTimeout(read, 0)
    const onKeyUp = (event) => {
      if (event.key === 'Escape') {
        setPill(null)
        return
      }
      if (event.key === 'E' && (event.ctrlKey || event.metaKey) && event.shiftKey) {
        // Ctrl/Cmd+Shift+E opens the current selection as a quote without a pointer.
        read()
        return
      }
      if (event.shiftKey) read()
    }
    const onPointerDown = (event) => {
      const target = event && event.target
      if (target && target.closest && target.closest('[data-cb-tutor-pill]')) return
      setPill(null)
    }
    document.addEventListener('pointerup', onPointerUp)
    document.addEventListener('pointerdown', onPointerDown)
    document.addEventListener('keyup', onKeyUp)
    return () => {
      document.removeEventListener('pointerup', onPointerUp)
      document.removeEventListener('pointerdown', onPointerDown)
      document.removeEventListener('keyup', onKeyUp)
    }
  }, [pill])
  if (!pill) return null
  return jsx('button', {
    type: 'button',
    'data-cb-tutor-pill': pill.blockId || 'text',
    'aria-label': `Ask the tutor about “${pill.text.slice(0, 60)}”`,
    onMouseDown: (event) => event.preventDefault(),
    onClick: () => {
      const current = context || {}
      armTutorQuote({
        text: pill.text,
        blockId: pill.blockId,
        courseId: current.courseId || null,
        objectiveId: current.objectiveId || null,
        source: 'selection'
      })
      requestTutorFocus()
      setPill(null)
    },
    style: {
      position: 'fixed',
      zIndex: 60,
      left: `${Math.max(8, Math.round(pill.x))}px`,
      top: `${Math.max(8, Math.round(pill.y - 40))}px`,
      transform: 'translateX(-50%)',
      display: 'inline-flex',
      alignItems: 'center',
      gap: '0.3rem',
      minHeight: '28px',
      padding: '0.2rem 0.6rem',
      border: '1px solid var(--cb-ink)',
      borderRadius: '2px',
      background: 'var(--cb-paper-raised)',
      color: 'var(--cb-ink)',
      fontFamily: CB_SANS,
      fontSize: CB_TYPE.caption,
      fontWeight: 600,
      cursor: 'pointer'
    },
    children: 'Ask tutor'
  })
}

/**
 * The pane's data half. One rail, one thread per lesson run, and one explicit write per press.
 */
function TutorRailPane({ binding }) {
  const profile = binding.profile || currentScope().profile
  const library = useRpcQuery(
    'library.list',
    { filter: 'all', limit: 100 },
    `tutor-library-${binding.enrollment_id}`,
    backendSupports('library.list')
  )
  const row =
    library.data && Array.isArray(library.data.items)
      ? library.data.items.find((item) => item.enrollment_id === binding.enrollment_id)
      : null
  const objectiveId = binding.objective_id || (row && row.evidence_summary ? row.evidence_summary.current_objective_id : null)
  const courseId = row ? row.course_id : null
  const runId = binding.lesson_run_id || null
  const page = useRpcQuery(
    'lesson.page',
    { enrollment_id: binding.enrollment_id, objective_id: objectiveId },
    `tutor-page-${binding.enrollment_id}-${objectiveId}`,
    backendSupports('lesson.page') && Boolean(objectiveId)
  )
  const history = useRpcQuery(
    'tutor.history',
    {
      course_id: courseId,
      enrollment_id: binding.enrollment_id,
      objective_id: objectiveId,
      lesson_run_id: runId
    },
    `tutor-history-${binding.enrollment_id}-${objectiveId}-${runId}`,
    backendSupports('tutor.history') && Boolean(courseId && objectiveId && runId)
  )
  const revision = page.data ? page.data.revision : row ? row.revision : 0
  const check = useOpenCheck({
    enrollmentId: binding.enrollment_id,
    objectiveId,
    revision,
    enabled: Boolean(objectiveId) && backendSupports('check.open') && Boolean(page.data),
    implemented: backendWire.implemented
  })
  const practiceRead = useRpcQuery(
    'practice.state',
    { enrollment_id: binding.enrollment_id, objective_id: objectiveId },
    `tutor-practice-${binding.enrollment_id}-${objectiveId}`,
    backendSupports('practice.state') && Boolean(objectiveId)
  )

  const quote = useTutorQuote()
  const focusTick = useTutorFocusTick()
  const [mode, setMode] = useState('ask')
  const [draft, setDraft] = useState('')
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState(null)
  const [failure, setFailure] = useState(null)
  const [localTurns, setLocalTurns] = useState([])
  const [fenced, setFenced] = useState(0)
  const [hintUsed, setHintUsed] = useState(false)
  const [width, setWidth] = useState(0)
  const rootRef = useRef(null)
  const endNonce = useRef(null)
  const autoPractice = useRef(false)

  // The pane is not the route: measure the rail itself, so a 460 px window and a 1049 px window
  // with a chat beside it both choose the sheet/side layout from the space the rail really has.
  useEffect(() => {
    if (typeof window === 'undefined' || typeof document === 'undefined') return undefined
    const node = rootRef.current
    if (!node) return undefined
    const read = () => {
      const rect = node.getBoundingClientRect()
      if (rect && rect.width > 0) setWidth(Math.round(rect.width))
    }
    read()
    let observer = null
    if (typeof ResizeObserver === 'function') {
      observer = new ResizeObserver(read)
      observer.observe(node)
    }
    return () => {
      if (observer) observer.disconnect()
    }
  }, [])

  const adoptRevision = useCallback((value) => {
    const next = Number(value)
    if (Number.isFinite(next) && next > 0) setFenced((current) => Math.max(current, next))
  }, [])
  useEffect(() => {
    adoptRevision(revision)
  }, [revision, adoptRevision])
  useEffect(() => {
    adoptRevision(history.data && history.data.revision)
  }, [history.data, adoptRevision])

  useEffect(() => {
    if (!focusTick) return
    if (typeof document === 'undefined') return
    const node = document.getElementById('cb-tutor-input')
    if (node && typeof node.focus === 'function') node.focus()
  }, [focusTick])

  useEffect(() => {
    // A history read replaces the optimistic turns it now contains; it never concatenates twice.
    if (history.status === 'ready') setLocalTurns([])
  }, [history.status, history.data])

  const blockIndex = cbTutorBlockIndex(page.data)
  const sourceIndex = {}
  for (const source of (page.data && page.data.sources) || []) {
    if (source && source.source_id) sourceIndex[source.source_id] = source
  }
  const glossary = cbTutorGlossary(page.data)
  const historyTurns = cbTutorTurns(history.data)
  const turns = historyTurns.concat(localTurns)
  const declaration = cbTutorPracticeDeclaration(check.check)
  const practiceSession = practiceRead.data && practiceRead.data.state !== 'none' ? practiceRead.data : null
  const practiceTranscript = (practiceSession && practiceSession.transcript) || (practiceRead.data && practiceRead.data.transcript) || []
  const practiceVerdict = practiceSession ? practiceSession.verdict : null
  const practiceFeedbackLine = practiceFeedback({
    verdict: practiceVerdict,
    criteria: (practiceSession && practiceSession.criteria) || [],
    learnerTurns: cbTutorLearnerTurnCount(practiceTranscript),
    targets: (declaration && declaration.targets) || []
  })

  const section = page.data && page.data.section
  const runtime = page.data && page.data.runtime
  const objectiveTitle = section ? section.title : (history.data && history.data.context ? history.data.context.objective_title : null)
  const contextChip = section && section.ordinal ? `Section ${section.ordinal}` : objectiveId ? 'This section' : ''
  const lessonChanged = Boolean(
    runtime && runtime.lesson_run_id && runId && String(runtime.lesson_run_id) !== String(runId)
  )
  const hintAvailable = Boolean(check.check) && cbTutorHintAvailable(check.check) && backendSupports('lesson.assist')
  const practiceAvailable = Boolean(
    declaration &&
    backendSupports('practice.state') &&
    backendSupports('practice.start') &&
    backendSupports('practice.end')
  )

  // The ask path needs a bound run: that is the only place `no-lesson` belongs.
  const askState =
    !objectiveId || !runId
      ? 'no-lesson'
      : lessonChanged && !localTurns.length
        ? 'lesson-changed'
        : library.status === 'error' && !library.data
          ? 'unavailable'
          : (library.status === 'loading' && !row) || (page.status === 'loading' && !page.data) || (history.status === 'loading' && !history.data)
            ? 'loading'
            : 'ready'
  const practiceState = practiceRead.status === 'loading' && !practiceRead.data ? 'loading' : 'ready'
  // Practice is keyed by (enrollment_id, objective_id) and needs no lesson run, so `no-lesson` is
  // an ask-path state only. A bound lesson with an open practice check still renders the practice
  // in the rail even when this chat carries no run id.
  const practiceHere = mode === 'practice' && practiceAvailable && Boolean(objectiveId)
  const railState =
    failure === 'provider'
      ? 'provider-failure'
      : failure === 'unavailable'
        ? 'unavailable'
        : practiceHere
          ? practiceState
          : askState

  const fence = Math.max(Number(fenced) || 0, Number(revision) || 0, Number(row && row.revision) || 0)

  /**
   * One explicit ask. The only callers are a press (Ask, Say it, or the Hint action); a selection,
   * a quote chip or a glossary card prepares this payload and never invokes it.
   */
  const performAsk = useCallback(
    async (payload) => {
      setBusy(true)
      setNotice(null)
      setFailure(null)
      const response = await rpc('tutor.ask', payload, {
        idempotencyKey: newOperationId(`tutor-${payload.mode}`),
        expectedRevision: fence
      })
      setBusy(false)
      if (!response.ok) {
        const code = response.error && response.error.code
        setFailure(code === 'HOST_UNAVAILABLE' ? 'unavailable' : 'provider')
        setNotice(response.error ? `${code || 'ERROR'}: ${describeError(response.error)}` : null)
        return false
      }
      adoptRevision(response.revision)
      const result = response.result || {}
      if (result.state === 'provider_failure') {
        setFailure('provider')
        return false
      }
      const learnerTurn = {
        id: `local-learner-${Date.now()}`,
        ordinal: turns.length + 1,
        role: 'learner',
        text: payload.question,
        block_id: payload.block_id,
        selected_text: payload.selected_text,
        citations: [],
        state: null
      }
      const tutorTurn = result.turn
        ? {
            ...result.turn,
            ordinal: turns.length + 2,
            state: result.state || null,
            citations: Array.isArray(result.citations) && result.citations.length ? result.citations : result.turn.citations
          }
        : null
      setLocalTurns((current) => (tutorTurn ? current.concat([learnerTurn, tutorTurn]) : current.concat([learnerTurn])))
      setDraft('')
      clearTutorQuote()
      if (result.state === 'answer_withheld') {
        setNotice('The answer stays hidden while the check is open. The hint path is the way forward.')
      }
      if (payload.mode === 'practice') practiceRead.reload()
      else history.reload()
      return true
    },
    [fence, adoptRevision, turns.length, practiceRead, history]
  )

  const send = useCallback(async () => {
    const payload = tutorAskPayload({
      courseId,
      enrollmentId: binding.enrollment_id,
      objectiveId,
      lessonRunId: runId,
      question: draft,
      quote,
      mode
    })
    if (!payload || busy) return
    if (quote && quote.blockId && !blockIndex[quote.blockId]) {
      setNotice('That excerpt belongs to another section. Select it again in this one.')
      return
    }
    await performAsk(payload)
  }, [courseId, binding.enrollment_id, objectiveId, runId, draft, quote, mode, busy, blockIndex, performAsk])

  const askHint = useCallback(async () => {
    if (!hintAvailable || busy || hintUsed) return
    setBusy(true)
    setNotice(null)
    const recorded = await rpc(
      'lesson.assist',
      { enrollment_id: binding.enrollment_id, objective_id: objectiveId, kind: 'hint_request' },
      { idempotencyKey: newOperationId('tutor-hint'), expectedRevision: fence }
    )
    if (!recorded.ok) {
      setBusy(false)
      setNotice(recorded.error ? `${recorded.error.code}: ${describeError(recorded.error)}` : 'The hint could not be recorded.')
      return
    }
    adoptRevision((recorded.result && recorded.result.revision) || recorded.revision)
    setHintUsed(true)
    const payload = tutorAskPayload({
      courseId,
      enrollmentId: binding.enrollment_id,
      objectiveId,
      lessonRunId: runId,
      question: TUTOR_HINT_QUESTION,
      quote: null,
      mode: 'ask'
    })
    if (!payload) {
      setBusy(false)
      return
    }
    setBusy(true)
    setNotice('Hint recorded. This answer is marked hinted; the check still owns the verdict.')
    await performAsk(payload)
  }, [
    hintAvailable,
    busy,
    hintUsed,
    binding.enrollment_id,
    objectiveId,
    courseId,
    runId,
    fence,
    adoptRevision,
    performAsk
  ])

  const startPractice = useCallback(async () => {
    if (!practiceAvailable || busy) return
    setBusy(true)
    setNotice(null)
    const response = await rpc(
      'practice.start',
      { enrollment_id: binding.enrollment_id, objective_id: objectiveId },
      { idempotencyKey: newOperationId('tutor-practice-start'), expectedRevision: fence }
    )
    setBusy(false)
    if (!response.ok) {
      setNotice(response.error ? `${response.error.code}: ${describeError(response.error)}` : 'The practice could not start.')
      return
    }
    adoptRevision((response.result && response.result.revision) || response.revision)
    endNonce.current = null
    practiceRead.reload()
  }, [practiceAvailable, busy, binding.enrollment_id, objectiveId, fence, adoptRevision, practiceRead])

  const endPractice = useCallback(async () => {
    if (busy) return
    const session = practiceRead.data
    const checkId = (session && session.check_id) || (check.check && check.check.check_id)
    const checkVersion = (session && session.check_version) || (check.check && check.check.check_version)
    if (!checkId || !checkVersion) {
      setNotice('The practice check could not be named, so nothing was graded.')
      return
    }
    if (!endNonce.current) endNonce.current = newOperationId('tutor-practice-end')
    setBusy(true)
    setNotice(null)
    const response = await rpc(
      'practice.end',
      {
        enrollment_id: binding.enrollment_id,
        check_id: checkId,
        check_version: Number(checkVersion),
        attempt_nonce: endNonce.current
      },
      { idempotencyKey: `tutor-end-${endNonce.current}`, expectedRevision: fence }
    )
    setBusy(false)
    if (!response.ok) {
      setNotice(practiceRefusalCopy(response.error) || (response.error ? describeError(response.error) : 'The practice could not be ended.'))
      return
    }
    adoptRevision(response.revision)
    endNonce.current = null
    practiceRead.reload()
    history.reload()
    page.reload()
    check.reload()
  }, [
    busy,
    practiceRead,
    check.check,
    binding.enrollment_id,
    fence,
    adoptRevision,
    history,
    page,
    check
  ])

  const openCitation = useCallback(
    (citation) => {
      if (!citation) return
      if (citation.kind === 'source') {
        requestIntent({ kind: 'lesson-block', row, objectiveId, blockId: null })
        return
      }
      requestIntent({ kind: 'lesson-block', row, objectiveId, blockId: citation.id })
    },
    [row, objectiveId]
  )

  const addTermQuote = useCallback(
    (entry) => {
      if (!entry) return
      armTutorQuote({
        text: entry.term,
        blockId: entry.blockId || null,
        courseId,
        objectiveId,
        source: 'glossary'
      })
      requestTutorFocus()
    },
    [courseId, objectiveId]
  )

  const retry = useCallback(() => {
    setFailure(null)
    setNotice(null)
    library.reload()
    page.reload()
    history.reload()
    practiceRead.reload()
    check.reload()
  }, [library, page, history, practiceRead, check])

  const modeChange = useCallback(
    (next) => {
      if (next !== 'ask' && next !== 'practice') return
      if (next === 'practice' && !practiceAvailable) return
      // A learner who has already chosen a mode owns the rail. Arming the auto-open guard here is
      // what keeps a practice check that lands after this click from moving them: the effect below
      // opens practice once, and only for a learner who has not chosen.
      autoPractice.current = true
      setMode(next)
      setFailure(null)
      setNotice(null)
    },
    [practiceAvailable]
  )

  // A conversation-practice check on a bound lesson that has no lesson run. The rail's Ask mode
  // needs a run to hold a thread, and the practice commands are keyed by (enrollment_id,
  // objective_id) and need none, so the practice is both reachable and the useful opening mode.
  const practiceCheck =
    check.check && cbTutorPracticeDeclaration(check.check) ? check.check : null
  const runBound = Boolean(runId)
  useEffect(() => {
    if (autoPractice.current) return
    if (runBound || !practiceCheck || !practiceAvailable || !objectiveId) return
    autoPractice.current = true
    setMode('practice')
  }, [runBound, practiceCheck, practiceAvailable, objectiveId])
  // With no run there is no rail thread to write practice turns into: the learner's turns are
  // written by the bound chat, so the pane shows the shipped PracticeSurface (the same surface the
  // lesson check has always used) instead of a second practice implementation.
  const practiceSurface =
    practiceCheck && !runBound
      ? jsx(PracticeSurface, {
          enrollmentId: binding.enrollment_id,
          objectiveId,
          check: practiceCheck,
          revision: fence,
          implemented: backendWire.implemented,
          bindingState: binding.status || 'active',
          onCommitted: retry
        })
      : null
  // Once the learner picks a mode, the rail never moves them again: the auto-open above fires once.
  const rail = jsx(TutorRail, {
    state: railState,
    width,
    courseTitle: (page.data && page.data.course && page.data.course.title) || (row && row.title) || '',
    sectionTitle: section ? section.title : '',
    objectiveTitle,
    contextChip,
    turns,
    blockIndex,
    sourceIndex,
    glossary,
    checkOpen: Boolean(check.check),
    hint: hintAvailable || hintUsed ? { available: hintAvailable && !hintUsed, used: hintUsed } : null,
    mode,
    quote,
    draft,
    busy,
    notice,
    detached: Boolean(binding.status && binding.status !== 'active'),
    practice:
      mode === 'practice'
        ? {
            declaration,
            state: practiceRead.status === 'error' ? 'none' : (practiceSession && practiceSession.state) || 'none',
            transcript: practiceSession ? practiceTranscript : [],
            remaining: practiceSession ? practiceSession.remaining : null,
            verdict: practiceVerdict,
            criteria: (practiceSession && practiceSession.criteria) || [],
            feedback: practiceFeedbackLine
          }
        : null,
    practiceAvailable,
    practiceSurface,
    practiceError: mode === 'practice' && practiceRead.status === 'error' ? practiceRead.error : null,
    onModeChange: modeChange,
    onDraftChange: setDraft,
    onSend: send,
    onRemoveQuote: clearTutorQuote,
    onCitation: openCitation,
    onHint: askHint,
    onTermQuote: addTermQuote,
    onRetry: retry,
    onStartPractice: startPractice,
    onEndPractice: endPractice,
    onOpenSection: () => requestIntent({ kind: 'lesson-block', row, objectiveId, blockId: null }),
    onOpenCoursebook: () => host.navigate(ROUTE_PATH)
  })

  return jsx('div', {
    ref: rootRef,
    'data-cb-tutor-pane': binding.enrollment_id,
    'data-cb-tutor-run': runId || '',
    'data-cb-tutor-objective': objectiveId || '',
    style: { display: 'flex', flexDirection: 'column', gap: '0.35rem', minWidth: 0 },
    children: rail
  })
}

function CoursebookPane() {
  const { state, storedId, reload } = useSessionBinding()
  // The pane is part of the same scoped surface as the route: same token table, same mode, and
  // the same H-147 appearance/motion settings the learner chose on Home.
  const [panePrefs] = useCbHomePrefs()
  const hostMode = useCbMode()
  const cbMode = cbAppliedMode(hostMode, panePrefs.appearance)
  const systemReduced = useCbReducedMedia()
  const cbMotion = panePrefs.reducedMotion === 'reduce' || systemReduced ? cbMotionFor('reduced') : cbMotionFor('full')
  useEffect(() => {
    publishCbMotion(cbMotion)
  }, [cbMotion.reduced])
  const scopeProfile = currentScope().profile
  const routingUnavailable = profileRouteState.status === 'unavailable'
  const [bindNote, setBindNote] = useState(null)
  const attemptedBind = useRef(null)
  // Which bundled learner skill this chat's next turn loads. Read from the backend's own rule
  // (`GET /sessions/skill` -> coursebook.lesson_skills), the same function the pre_llm_call hook
  // calls, so the note cannot describe a different skill than the turn loads.
  const [skillNote, setSkillNote] = useState(null)

  useEffect(() => {
    if (!storedId) {
      setSkillNote(null)
      return undefined
    }
    let cancelled = false
    rest(`/sessions/skill?session_id=${encodeURIComponent(storedId)}`)
      .then((answer) => {
        if (cancelled) return
        setSkillNote(answer && answer.skill ? answer : null)
      })
      .catch(() => {
        if (!cancelled) setSkillNote(null)
      })
    return () => {
      cancelled = true
    }
  }, [storedId, state.status, state.binding])

  useEffect(() => {
    // A run this Desktop opened is armed. Bind it to the focused chat once that chat has a
    // durable id and no binding of its own — by the exact stored id, never the runtime id and
    // never "the newest chat". One attempt per stored id; the seam decides legality.
    if (!storedId || attemptedBind.current === storedId) return undefined
    if (state.status !== 'ready' || state.binding) return undefined
    if (!pendingBindFor(scopeProfile)) return undefined
    let cancelled = false
    attemptedBind.current = storedId
    bindPendingChat(storedId, scopeProfile).then((response) => {
      if (cancelled || !response) return
      if (response.ok) {
        setBindNote('This lesson is bound to this chat.')
        reload()
      } else {
        setBindNote(`${response.code}: ${response.message || 'this chat could not be bound.'}`)
      }
    })
    return () => {
      cancelled = true
    }
  }, [storedId, state.status, state.binding, scopeProfile, reload])

  const openCoursebook = useCallback(() => {
    host.navigate(ROUTE_PATH)
  }, [])

  const resume = useCallback(async () => {
    const outcome = await resumeBoundSession(state.binding)
    if (!outcome.ok) {
      host.notify({ kind: 'warning', message: outcome.message })
      return
    }
  }, [state.binding])

  let body
  const armedRun = pendingBindFor(scopeProfile)
  if (armedRun && (state.status === 'no-session' || state.status === 'idle')) {
    // H-64: a fresh run this Desktop just started is armed to this exact chat. A blank "no durable
    // chat yet" panel here is where the old Start lesson dead end ended up; this state names the
    // run, the objective and the one action that turns this chat into a lesson.
    body = jsx(sdk.PanelEmpty, {
      icon: 'book',
      title: armedRun.objectiveTitle ? `Lesson run ready: ${armedRun.objectiveTitle}` : 'Lesson run ready',
      description:
        'This chat belongs to that lesson. Send the first message and Coursebook connects it to the run; ' +
        'the section stays open beside it with the teaching, the sources and the check.',
      action: jsx(sdk.Button, { variant: 'secondary', size: 'sm', onClick: openCoursebook, children: 'Open the section' })
    })
  } else if (state.status === 'no-session' || state.status === 'idle') {
    body = jsx(sdk.PanelEmpty, {
      icon: 'book',
      title: 'No lesson chat open',
      description:
        'A lesson runs in a chat. Open Coursebook, pick a course and start a run; the teaching stays beside the chat once it begins.',
      action: jsx(sdk.Button, { variant: 'secondary', size: 'sm', onClick: openCoursebook, children: 'Open Coursebook' })
    })
  } else if (state.status === 'loading') {
    body = jsx('div', { className: 'py-6', children: jsx(sdk.Loader, { label: 'Reading this chat’s binding' }) })
  } else if (state.status === 'unavailable') {
    const code = state.error && state.error.code
    body =
      code === 'NOT_IMPLEMENTED'
        ? jsx(sdk.PanelEmpty, {
            icon: 'book',
            title: 'Lessons arrive with the learning kernel',
            description:
              'The backend is connected and answering, but this build has no kernel schema, so no ' +
              'session binding can exist yet. Nothing here is being guessed.',
            action: jsx(sdk.Button, { variant: 'secondary', size: 'sm', onClick: openCoursebook, children: 'Open Coursebook' })
          })
        : jsx(sdk.PanelEmpty, {
            icon: 'warning',
            title: 'Cannot read this chat’s binding',
            description: code ? `${code}: ${describeError(state.error)}` : describeError(state.error),
            action: jsx(sdk.Button, { variant: 'secondary', size: 'sm', onClick: openCoursebook, children: 'Open Coursebook' })
          })
  } else if (state.binding && storedId && state.binding.stored_session_id && state.binding.stored_session_id !== storedId) {
    // a binding for a chat that is no longer on screen is never rendered as this chat's lesson
    body = jsx('div', { className: 'py-6', children: jsx(sdk.Loader, { label: 'Reading this chat’s binding' }) })
  } else if (!state.binding) {
    // GM-012: the rail is a tutor, not a chat probe. A chat with no lesson is not an error and is
    // never told it is "not a Coursebook lesson"; it points at the one door that starts one.
    body = jsx(sdk.PanelEmpty, {
      icon: 'book',
      title: 'Open a lesson to ask the tutor.',
      description:
        'The tutor answers about the section you are reading, with the lesson’s own words and sources. ' +
        'Open Coursebook, pick a section, and its chat brings the rail here.',
      action: jsx(sdk.Button, { variant: 'secondary', size: 'sm', onClick: openCoursebook, children: 'Open Coursebook' })
    })
  } else {
    body = jsx(TutorRailPane, { binding: state.binding })
  }

  return jsxs('div', {
    className: 'flex h-full min-h-0 flex-col px-3 py-2',
    'data-cb-stored-id': storedId || '',
    'data-cb-binding-id': (state.binding && state.binding.binding_id) || '',
    'data-cb-scope': cbMode,
    'data-cb-motion': cbMotion.preference,
    style: { ...cbScopeStyle(cbMode), ...cbHostVars(panePrefs.appearance) },
    children: [
      jsx(CbLabel, { children: 'Coursebook' }),
      routingUnavailable
        ? jsx('div', {
            className: 'pb-2 text-xs text-(--ui-text-secondary)',
            role: 'status',
            'data-cb-routing': 'unavailable',
            children:
              'Routing unavailable: Coursebook could not read this window’s profile routes, so ' +
              'requests go without a connection id. Reopen the pane or restart Desktop; on a ' +
              'single-connection install nothing is lost.'
          })
        : null,
      bindNote ? jsx('div', { className: 'pb-2 text-xs text-(--ui-text-secondary)', children: bindNote }) : null,
      skillNote
        ? jsx('div', {
            className: 'pb-2 text-xs text-(--ui-text-secondary)',
            'data-cb-skill': skillNote.skill,
            'data-cb-skill-reason': skillNote.reason || '',
            children:
              skillNote.reason === 'lesson_binding'
                ? `Tutor skill: ${skillNote.skill} — loads on this chat's next message.`
                : `Coach skill: ${skillNote.skill} — no live lesson run for this chat.`
          })
        : null,
      body
    ]
  })
}

/**
 * Reactive read of a host atom. The host's own `useValue` did not re-render this pane when the
 * focused chat changed (the pane stayed pinned to the binding of the chat it first mounted with,
 * so a bound lesson could outlive its chat), so subscribe directly and keep the value in local
 * state. Falls back to the host hook when the atom exposes no subscription.
 */
function useHostValue(atom) {
  const read = useCallback(() => (atom && typeof atom.get === 'function' ? atom.get() : atom), [atom])
  const [value, setValue] = useState(read)
  useEffect(() => {
    setValue(read())
    if (!atom) return undefined
    if (typeof atom.subscribe === 'function') return atom.subscribe((next) => setValue(next))
    if (typeof atom.listen === 'function') return atom.listen((next) => setValue(next))
    if (typeof sdk.useValue === 'function') return undefined
    return undefined
  }, [atom, read])
  return value
}

/**
 * The focused chat's binding, read by its STORED id only.
 *
 * Four honest states: no durable chat yet, loading, could-not-ask, and answered (bound or not).
 * `runtimeId` is returned for diagnostics; it is never sent to `binding.get`.
 */
function useSessionBinding() {
  const storedId = useHostValue(host.state.focusedStoredSessionId)
  const runtimeId = useHostValue(host.state.focusedSessionId)
  const [state, setState] = useState({ status: 'idle', binding: null, error: null })
  const [ticket, setTicket] = useState(0)
  const reload = useCallback(() => setTicket((value) => value + 1), [])

  useEffect(() => {
    if (!storedId) {
      setState({ status: 'no-session', binding: null, error: null })
      return undefined
    }
    let cancelled = false
    setState({ status: 'loading', binding: null, error: null })
    loadBinding({ storedSessionId: storedId })
      .then((response) => {
        if (cancelled) return
        if (response && response.ok) {
          setState({ status: 'ready', binding: response.result.binding, error: null })
        } else {
          setState({ status: 'unavailable', binding: null, error: (response && response.error) || null })
        }
      })
      .catch((error) => {
        if (!cancelled) {
          setState({
            status: 'unavailable',
            binding: null,
            error: { code: 'HOST_UNAVAILABLE', message: describeError(error) }
          })
        }
      })
    return () => {
      cancelled = true
    }
  }, [storedId, ticket])

  return { storedId, runtimeId, state, reload }
}

function ContractList() {
  const [state, setState] = useState({ status: 'loading', contracts: [], error: null })

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      try {
        const response = await fetchSchema()
        if (cancelled) return
        if (response && response.ok) {
          setState({ status: 'ready', contracts: response.result.contracts, error: null })
        } else {
          setState({ status: 'unavailable', contracts: [], error: response && response.error })
        }
      } catch (error) {
        if (!cancelled) setState({ status: 'unavailable', contracts: [], error })
      }
    })()
    return () => {
      cancelled = true
    }
  }, [])

  if (state.status === 'loading') return jsx(sdk.Loader, { label: 'Reading the contract inventory' })
  if (state.status === 'unavailable') {
    return jsx('div', {
      className: 'text-xs text-(--ui-text-secondary)',
      children: `Contract inventory unavailable. ${describeError(state.error)}`
    })
  }
  return jsx('div', {
    className: 'flex flex-col',
    children: state.contracts.map((entry) =>
      jsx(
        StatusRow,
        {
          label: entry.id,
          value: `v${entry.version}`,
          detail: `${entry.file} · ${String(entry.sha256).slice(7, 19)}…`
        },
        entry.id
      )
    )
  })
}

function SessionDiagnostics() {
  const runtimeId = useHostValue(host.state.focusedSessionId)
  const storedId = useHostValue(host.state.focusedStoredSessionId)
  const scope = currentScope()
  const implemented = backendWire.implemented ? Array.from(backendWire.implemented).sort() : null
  return jsxs('div', {
    className: 'flex flex-col',
    children: [
      jsx(StatusRow, {
        label: 'Runtime session id',
        value: runtimeId ? `${String(runtimeId).slice(0, 12)}…` : 'none',
        detail: 'Live gateway id. Valid for this turn only; never sent to binding.get.'
      }),
      jsx(StatusRow, {
        label: 'Stored session id',
        value: storedId ? `${String(storedId).slice(0, 12)}…` : 'none',
        detail: storedId
          ? 'Durable id used for bindings and for opening a lesson chat.'
          : 'A fresh chat has none until its first turn. Nothing falls back to the runtime id.'
      }),
      jsx(StatusRow, {
        label: 'Scope',
        value: scope.profile || 'unknown profile',
        detail: scope.connectionId ? `connection ${scope.connectionId}` : 'local source'
      }),
      jsx(StatusRow, {
        label: 'Wire contract',
        value: `cb.rpc v${backendWire.contractVersion}`,
        detail: implemented
          ? `${plural(implemented.length, 'implemented command', 'implemented commands')}: ${implemented.join(', ')}`
          : 'Backend method registry unavailable; commands are attempted, not assumed.'
      })
    ]
  })
}

function CoursebookSettings() {
  return jsxs('div', {
    className: 'flex flex-col gap-3',
    children: [
      jsx('div', {
        className: 'text-xs text-(--ui-text-secondary)',
        children:
          'Preferences appear here only when the code that reads them ships. The inventory below is ' +
          'read-only and shows the exact contracts this backend speaks.'
      }),
      jsx(CbLabel, { children: 'Session binding' }),
      jsx(SessionDiagnostics, {}),
      jsx(CbLabel, { children: 'Contracts' }),
      jsx(ContractList, {})
    ]
  })
}

